INSERT INTO "intelligence_events" ("id","type","title","summary","severity","confidence","status","content_hash","first_seen_at","last_updated_at","entities_json","mitre_matrix","created_at","updated_at") VALUES('evt_c20d1212-85b4-4c','vulnerability_exploitation','CVE-2026-62986','CVE-2026-62986 OpenEXR is the reference implementation and specification for the EXR image file format, widely used in the motion picture industry. In versions 3.3.0 through 3.3.12 and 3.4.0 through 3.4.13, the PyOpenEXR Python bindings return stale heap data when reading a crafted deep scanline EXR that uses layer-prefixed RGB channels. With the default channel coalescing (separate_channels=False), the wrapper groups channels such as left.R, left.G, and left.B into a single RGB sample array, but the lane-offset calculation in PyPart::setDeepSliceData() only recognizes the exact unprefixed nam','high',0.73,'HIGH','7e10acb38446433f5e44a0771e76d53c3d01541aac39b70e1dda6df6f28d422c','2026-08-25T19:24:18.000Z','2026-08-25T19:24:59.355Z','{"cves":["CVE-2026-62986"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["OpenEXR.File"],"ttps":[],"actors":[],"malware":[]}','[]','2026-08-25 19:24:59','2026-08-25 19:24:59');
