INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_5ab0dc31-07d','tg_0','14335','5bce8d5071c6dd91add5827865aa2fac498faf33040e766a6dc732c065230d04',replace('**Опубликован Armbian 26.8, дистрибутив для одноплатных компьютеров**\n\nОпубликован выпуск Linux-дистрибутива Armbian 26.8, предоставляющего компактное системное окружение для одноплатных компьютеров с процессорами на базе архитектур ARM, RISC-V и x86, поддерживающее различные модели Raspberry Pi, Odroid, Orange Pi, Banana Pi, Helios64, pine64,  Nanopi и Cubieboard на базе процессоров Allwinner,   Amlogic, Actionsemi, Freescale / NXP, Marvell Armada, Rockchip, Radxa  и Samsung Exynos.\n\n Подробнее:\nhttps://opennet.ru/66141/\nhttps://opennet.me/66141/','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["opennet.ru","opennet.me"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T07:32:05.000Z','2026-08-26 07:32:12','2026-08-26 07:32:12');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_1c9d3ba6-e7b','tg_0','987','d4899385ad062045c9f1f448043f3359503bfe732f6c0edc6521e2d86843c7b7',replace('🚨Tortoiseshell is evolving its infrastructure and expanding its operational footprint across Europe and the Middle East.\n\nIn our latest technical analysis, Group-IB Threat Intelligence uncovered new infrastructure and malware associated with the Iranian-nexus APT, including a reverse SSH tunneling tool disguised as wtsapi32.dll and TWOSTROKE C++ backdoor capable of command execution, file exfiltration, in-memory DLL execution, and host reconnaissance.\n\nOur research also identified additional C2 infrastructure and geographically named subdomains that may indicate a broader targeting profile.\n\nRead the full technical analysis to explore Tortoiseshell''s evolving toolset, infrastructure, C2 architecture, and defensive recommendations.\n\n#ThreatIntelligence #APT #CyberSecurity #Tortoiseshell','\n',char(10)),'Tortoiseshell is evolving its infrastructure and expanding its operational footprint across Europe and the Middle East. In our latest technical analysis, Group-IB Threat Intelligence uncovered new infrastructure and malware associated with the Iranian-nexus APT, including a reverse SSH tunneling tool disguised as wtsapi32.dll and TWOSTROKE C++ backdoor capable of command execution, file exfiltration, in-memory DLL execution, and host reconnaissance. Our research also identified additional C2 infrastructure and geographically named subdomains that may indicate a broader targeting profile. Read','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["wtsapi32.dll"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T07:47:09.000Z','2026-08-26 07:47:16','2026-08-26 07:47:16');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_bb9b3275-a13','tg_0','8057','f0806ab198ece084fbb4216060c971f42d29587325a5c20c233a87db6ee574af',replace('🚨Cyber Alert ‼️\n\n🇮🇹Italy - 𝗦𝘁𝘂𝗱𝗶𝗼 𝗟𝗲𝗴𝗮𝗹𝗲 𝗘𝗦𝗘\n\nDire Wolf hacking group claims to have breached Studio Legale ESE, allegedly exfiltrating 420 GB of data. According to the post, stolen data include email backups, customer data and financial records.\n\nThreat actor: Dire Wolf\nSector: Legal and accounting activities\nData exposure (claimed): 420 GB\nData type: Email backups, customer data and financial records\nObserved: Aug 25, 2026\nStatus: Pending verification\nESIX©: 5.41\n\nFull details and impact assessment on HackRisk.io','\n',char(10)),'Cyber Alert ‼️ 🇮🇹Italy - 𝗦𝘁𝘂𝗱𝗶𝗼 𝗟𝗲𝗴𝗮𝗹𝗲 𝗘𝗦𝗘 Dire Wolf hacking group claims to have breached Studio Legale ESE, allegedly exfiltrating 420 GB of data. According to the post, stolen data include email backups, customer data and financial records. Threat actor: Dire Wolf Sector: Legal and accounting activities Data exposure (claimed): 420 GB Data type: Email backups, customer data and financial records Observed: Aug 25, 2026 Status: Pending verification ESIX©: 5.41 Full details and impact assessment on HackRisk.io','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["HackRisk.io"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T07:48:05.000Z','2026-08-26 07:48:11','2026-08-26 07:48:11');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_a0c312bd-384','tg_0','23242','3c3a8b50f0c9c248a05bdd5d412f7eaac911e9c9364349e80af87cd4f63f8cad',replace('▶️ **Уже через 10 минут начинаем эфир AM Live!**\n\nСегодня говорим об автоматизированной проверке защищённости.\n\nВместе с экспертами обсудим:\n— почему ежегодного пентеста уже недостаточно;\n— какие инструменты помогают находить реальные риски;\n— как встроить автоматизированные проверки в процессы ИБ;\n— и как использовать результаты проверок для снижения киберрисков.\n\n🔗 Подключайтесь к эфиру и задавайте вопросы экспертам в чате AM Live','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T07:50:10.000Z','2026-08-26 07:50:18','2026-08-26 07:50:18');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_6a25e9ac-39b','tg_0','4354','bb29f0a71dd7b52e6efafaa099d49fb19d9d4ecfa5d2cb47faa2621dff90d8a5',replace('⚡️ **Type-driven development в Rust, часть 2/5: контракты между компонентами — от эксперта F6.**\n\nПродолжаем серию о type-driven development в Rust. В первой части типы отвечали за данные: какие значения возможны и какие комбинации допустимы. Во второй разработчик MXDR F6 Никита Тимофеенко разбирает контракты между компонентами: как записать их в типах, чтобы нарушение контракта не компилировалось.\n\n**Во втором материале — три механизма:\n**\n▪️ traits;\n▪️ associated types;\n▪️ const generics.\n\n**Эксперт разобрал каждый по схеме:\n**\nпроблема ➡️ решение ➡️ хорошие практики ➡️ как это используют известные крейты или std библиотека.\n\n**Отдельно — CGP (Context-Generic Programming):** что делать, когда одному типу нужно несколько реализаций одного трейта, а правило когерентности разрешает одну.\n\nПримеры во всей серии — из биржевой торговли, но сами приёмы работают в любом домене со сложными состояниями и правилами их изменения.\n\n➡️ **ЧИТАТЬ НА HABR**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:00:01.000Z','2026-08-26 08:00:07','2026-08-26 08:00:07');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_21816136-2fa','tg_0','3939','bc10a8dfc393f519a5416496f84fab3c9fbd50fc972f962d6a5840fabf485915',replace('⌨️ **Мошенники запустили десятки фальшивых ИИ-платформ для «инвестиций»**\n\nЗлоумышленники обещают автоматическую торговлю с помощью нейросетей и высокую доходность, а после регистрации убеждают внести первый депозит.\n\nПользователю показывают вымышленные сделки и растущий баланс, хотя реальных инвестиций не происходит.\n\n😎  **Здесь о кибербезе**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:00:01.000Z','2026-08-26 08:00:09','2026-08-26 08:00:09');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_315819ac-db8','tg_0','7664','170b70b146dbd80bfc71fe487dfd7e110110f4f57d3475248c2739dee5368f8d',replace('**Злоумышленники используют ScreenConnect для скрытой доставки AsyncRAT**\n \nАнализ подозрительной активности, связанной с процессом легитимной утилиты ScreenConnect, **помог нашим экспертам раскрыть масштабную кампанию**, в которой эта утилита применялась для установки троянца AsyncRAT. Предположительная цель кампании — кража учётных данных жертв, а также получение доступа к их устройствам и корпоративным сетям для последующей перепродажи.\n \nЗлоумышленники развернули сеть из более чем 90 вредоносных доменов, маскирующихся под официальные ресурсы популярного софта (OBS Studio, DNS Jumper, Bandicam и др.). Они использовали поисковую оптимизацию, чтобы **их сайты отображались в первых строчках выдач **Google, Яндекс и других поисковых систем.\n\nКогда пользователь запускал установщик, вместе с желаемой программой без его ведома загружалась и утилита ScreenConnect. Атакующие использовали её для развёртывания трояна удалённого доступа AsyncRAT, чтобы получить контроль над устройством: на скомпрометированном устройстве **запускались скрипты, которые добавляли исключения в настройки встроенного антивируса Windows Defender**, обеспечивали закрепление в системе и **внедряли AsyncRAT в легитимный процесс**.\n \nВ нашей статье на Kaspersky Daily рассказываем, как могут выглядеть атаки с использованием утилиты ScreenConnect и как организациям защититься от них.\n\nПодробности, исследование инфраструктуры злоумышленников, а также индикаторы компрометации и правила детектирования угрозы — в материале на Securelist.\n\nKaspersky 💙 ВК | 💬 Max | 📝 Дзен\n💬Порвали два трояна в Max','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Malware: AsyncRAT Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":["AsyncRAT"]}','SUCCEEDED','2026-08-26T08:02:38.000Z','2026-08-26 08:02:45','2026-08-26 08:02:45');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_0268c7d4-c9c','tg_0','587','339df21f2e6a6346e69df38e9630c511dbd0853340651820b3eb8b2a024c1fbc',replace('Приглашаем на курс для прокачки навыков архитектора и проектировщика, которые важны для профессионального роста программиста.\n\n🌐 **С курсом «Системный дизайн высоконагруженных проектов» вы:**\n \n▪️изучите ключевые фундаментальные паттерны и получите навыки проектирования проектов с миллионной аудиторией (балансировка, масштабирование апп/кешей/субд, высокая доступность и кластерные решения, шардинг, CAP/PACELS, консистентность, саги, транзакционные очереди и многое другое)\n▪️поупражняетесь в проектировании и получите обратную связь на реальных задачах: магазин/маркетплейс, такси/доставка, обьявления, соцсети, дейтинг, игры, википедия, мессенжер, CDN, хранилище файлов, онлайн-кинотеатр, счетчики, удаленный мониторинг, интеграционные вебхуки, рассылки и тд.\n▪️ научитесь планировать нагрузку и связывать \nбизнес-показатели с нефункциональными требованиями к системе\n▪️ попрактикуемся в проведении и прохождения секций системного дизайна на интервью.\n\nВсё в формате живых онлайн-сессий (лекции, брейнштормы, презентации домашних проектов).\n\n🤩 **Кто мы:** R&D-центр Devhands.ru. Основатель школы и автор курса Алексей Рыбак, ex-СТО Badoo, с 20-летним опытом высоконагруженных проектов и управления глобальными технологическими организациями. \n\n🗓 Старт 7 сентября, изучаем программу, записываемся здесь\n\nРеклама. ИП Рыбак А.А. ИНН 771407709607 Erid: 2VtzqvimBRf','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["Devhands.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:04:06.000Z','2026-08-26 08:04:15','2026-08-26 08:04:15');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_b847fe98-388','tg_0','2219','c4eb80adbf45c8d6cfe819008e12ac0b431a6cb0b30a0d1621621e3e4f03c398',replace('**👍**** Годнота для фронтендеров: 160+ бесплатных 3D-заготовок**\n\nВ ThreeUI лежат:\n🫡 3D-компоненты;\n🫡 Шейдеры;\n🫡 Анимации;\n🫡 Шаблоны лендингов;\n🫡 Готовые исходники и промпты для агентов.\n\nБерём исходники, скармливаем агенту и быстро переделываем под свой проект.\n\n📱** ****VISION ****| ****Мы в MAX**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:11:01.000Z','2026-08-26 08:11:09','2026-08-26 08:11:09');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_f4d72aeb-0d3','tg_0','8060','6ade55551914d39da9ab79537131554d944ffcd2c00493da8c1d733e20e0cb4a',replace('Meowciety403 holiday! \nhave a fun haha!..  https://skandax.nexus/\nif you guys need holiday? https://skandax.nexus/admin/dashboard\nand make a fun zzzz😼','\n',char(10)),'Meowciety403 holiday! have a fun haha!.. if you guys need holiday? and make a fun zzzz','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["skandax.nexus"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:12:18.000Z','2026-08-26 08:12:26','2026-08-26 08:12:26');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_d4e47b3c-402','tg_0','14336','0fe5a1cb47450aae40b6895e967106c6217d5b0d7d7db8a2ebaf4a946ba58f42',replace('**Первый выпуск mklinux для одновременного выполнения нескольких экземпляров ядра Linux**\n\nПредставлен первый публичный выпуск проекта Multikernel Linux (mklinux-v7.0-mk2), развивающего вариант ядра Linux, дополненный возможностью выполнения нескольких независимых экземпляров ядра на одном физическом компьютере  без использования гипервизора  и виртуализации. Каждый экземпляр ядра имеет прямой доступ к аппаратным ресурсам и может использоваться для запуска отдельных изолированных системных окружений. Первый выпуск основан на ядре Linux 7.0 и содержит сборочную настройку CONFIG_MULTIKERNEL, при отключении которой ядро становится полностью аналогично штатному ядру 7.0. Из архитектур CPU пока поддерживается только x86_64.\n\n Подробнее:\nhttps://opennet.ru/66142/\nhttps://opennet.me/66142/','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["opennet.ru","opennet.me"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:22:05.000Z','2026-08-26 08:22:12','2026-08-26 08:22:12');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_ca9e6dd2-91a','tg_0','23244','5dae0cfa2d228659ca8c07d54978258713bf535bd835f8afb6d59659e0d9c394',replace('**Росфинмониторинг получит прямой доступ к данным о платежах через СБП**\n\nС 1 сентября Росфинмониторинг начнёт напрямую получать от Национальной системы платёжных карт сведения об операциях по картам «Мир», переводах через СБП и платежах по единому QR-коду. Запрашивать эти данные через банки финразведке больше не придётся.\n\n🔥 AM Live','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:23:01.000Z','2026-08-26 08:23:07','2026-08-26 08:23:07');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_ee760c52-f6a','tg_0','2297','64b2c1a28c47049b5f18121c6a02c4656f9e80c0b2ceaa6ee457cb40c016d008',replace('📊**Тенденции SOC по версии Gartner**\n\nПропустили обновление гартнеровского Hype Cycle for Security Operations, прошедшего в начале лета. Как обычно, авторы попытались сличить ~~маркетинг производителей~~ ожидания и реальность, и пришли к выводу, что ~~вода мокрая~~ сразу несколько ключевых компонентов всех ИБ-программ меняют своё место в архитектуре SOC. В первую очередь это SIEM, XDR, управление уязвимостями и киберразведка. \n**\nДве роли SIEM. **Решение вечных проблем SIEM со сбором достаточных, но не избыточных данных, а также сложностью интеграции, плюс прохождение нового квеста по внедрению ИИ, идёт двумя разными способами. Первый — интегрированная платформа SOC (ISOC), все функции центра мониторинга в одной упаковке, от мониторинга до реагирования. Второй — SIEM теряет интерфейс и становится озером данных ИБ (security data lake), в который ныряют различные агенты и специализированные решения. При этом XDR прочат ту же дорогу, что и SOAR годом ранее — интеграция в платформы EDR и ISOC в качестве функции.\n\n**Управление уязвимостями получает апгрейд до CTEM, то есть непрерывного управления экспозицией. **Это не новая позиция Гартнера, но в этом году они получили прекрасный набор дополнительных аргументов — от роста числа уязвимостей до потери их сплошного покрытия авторитетами вроде NVD. По смелым ожиданиям, топовые решения будут объединять платформу постоянного мониторинга и приоритизации угроз с непрерывной оценкой защищённости, поставляемой как услуга (сюда входят и red teaming, и bug bounty, и даже киберучения).**\n\nГлубокая интеграция киберразведки.** Предполагается, что от ручной оценки аналитиком и применения TI в изолированных сценариях, компании перейдут к интеграции данных TI в оценку активов, уязвимостей, гипотез детектирования, где TI будет помогать автоматически расставлять приоритеты. Подобные системы будут в рамках одного процесса совместно использовать различные источники внешних сигналов и внутреннюю телеметрию. \n\n**Два сорта ИИ.** ИИ-ассистенты и ИИ-агенты SOC рассматриваются как две отдельные категории, где ассистенты включаются в существующие продукты и, например, помогают читать логи или искать данные, а агенты самостоятельно действуют внутри SIEM, EDR, IAM, и так далее.  Первая категория стремительно «остывает», к ней падает интерес, зато вторая находится прямо на пике. При этом авторы предупреждают, что внимание к агентам опережает их реальную зрелость, а основным риском 2026 является agent washing, когда нечто, продаваемое как ИИ-агент, является LLM, наспех прикрученной к продукту позапрошлого года.\n\n#SOC #CISO @П2Т','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:30:29.000Z','2026-08-26 08:30:35','2026-08-26 08:30:35');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_e3a654e0-d09','tg_0','5706','f6cfd73ef1295bad17a46eab4b5dad727f32bb2642156886459caeef09256aad',replace('**Сделки на 300 млн ₽, отказ от кредитов и маркетплейсов**\n\n«Говорит дело» — новый проект Яндекс Пэй о тех, кто строит бизнес и знает цену каждому решению.\n\nОснователи Poison Drop, GRI, STAYA и других проектов рассказывают о том, что реально работает.\n\nБез заготовленных речей, только живой опыт, цифры и ошибки, на которых учатся. Про масштабирование, платёжные инструменты, управление и принятие решений, когда нет готовых ответов.\n\nСмотрите и забирайте инсайты! \n\n**Узнать больше**\n\n#реклама 16+\npay.yandex.ru\nО рекламодателе','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["pay.yandex.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:34:06.000Z','2026-08-26 08:34:13','2026-08-26 08:34:13');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_9ce3fedb-843','tg_0','3677','714adda9353a6f130f35909ae1a60efe6e89df751f7308c2ef5cbbe7cdc78120',replace('**Выходим на широкие Кинопоиск-экраны!  **\n\nКак могли заметить самые внимательные читатели этого блога, я люблю путешествовать и фотографировать. \n\nА также иногда делать фильмы про путешествия... И парочка из них добралась до Кинопоиска. Итак, вашему вниманию:\n\n❄️ Тикси и прочие очень северные российские края, да ещё и зимой! \n\n🐼 Китай, не очень у нас известный, а именно его запад – немного провинции Сычуань, а также Цинхай и Ганьсу. Про некоторые отсмотренные места на русском языке почти нет информации – только у меня! \n\nЖелаю приятного просмотра!','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:34:23.000Z','2026-08-26 08:34:30','2026-08-26 08:34:30');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_ab287f49-08d','tg_0','8980','f61439ad8c4175fd35446f89e12b5a67135fcd00f59b68f5620281fc9614470c','Hey there El, and welcome to SWIPING CHAMBERS🎧💻! How are you?','Hey there El, and welcome to SWIPING CHAMBERS! How are you?','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T08:59:35.000Z','2026-08-26 08:59:42','2026-08-26 08:59:42');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_2fd682c4-ab0','tg_0','2891','6b6fd95342df969be8a5a88b9d34aeee7e6b210b581548cbf682d38757ce97d6',replace('📣 **Ждем ваш фидбэк**\n\nДавно заметили, что можно улучшить в сайте bi.zone? Или точно знаете, как повысить его функциональность? \n\nБудем благодарны, если примете участие в наших закрытых опросах и поделитесь своим мнением — мы готовы прислушаться.\n\nДля этого заполните короткую анкету всего из трех вопросов. Мы добавим вас в базу респондентов и обратимся при проведении следующего исследования.\n\nЗа участие мы приготовили приятные бонусы!\n\n➡️**Заполнить анкету**\n\n💬 Мы в MAX','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["bi.zone"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:03:41.000Z','2026-08-26 09:03:48','2026-08-26 09:03:48');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_171d88a2-ae6','tg_0','3679','db023fed1945a0364801a9ebd5d8757cc5c66a3425e63743ea522f144a16a18a',replace('**Выходим на широкие Кинопоиск-экраны!  **\n\nКак могли заметить самые внимательные подписчики моего канала, в свободное от работы время я люблю путешествовать и фотографировать. \n\nА также иногда делать фильмы про путешествия... И парочка из них добралась до Кинопоиска. Итак, вашему вниманию:\n\n❄️ Тикси и прочие очень северные российские края, да ещё и зимой! \n\n🐼 Китай, не очень у нас известный, а именно его запад – немного провинции Сычуань, а также Цинхай и Ганьсу. Про некоторые отсмотренные места на русском языке почти нет информации – только у меня! \n\nЖелаю приятного просмотра!','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:12:02.000Z','2026-08-26 09:12:09','2026-08-26 09:12:09');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_754f8760-8b5','tg_0','3154','47c8f0d00f94f505fcb4db3080d66b4298fb19f379033c23d9f0e525d9a25c22',replace('**Как обнаружить атаку на Active Directory, когда в логах всё чисто?**\n\nВ реальной инфраструктуре атакующий не оставляет очевидных следов. Чтобы его найти, нужно сначала самому пройти путь атаки — от первого доступа до захвата домена. \n\n**На курсе Codeby по анализу защищённости AD** вы отрабатываете всё на практике:** 30**+** виртуальных машин, которые вам** **предстоит скомпрометировать и в них** **закрепиться**.\n\n**Внутри**: \n⏺️AD-сети на миксе Windows/Linux\n⏺️Поиск слабых конфигураций, добыча критичных данных, продвижение по инфраструктуре\n⏺️Захват и укрепление позиций в домене \n⏺️Разбор и применение популярных эксплойтов\n\n**Авторы курса**: HackerRalf (Михаил Порываев) и BlackRabbit (Павел Никитин), 5-кратные победители The Standoff. \n\nПри оплате курса сразу **дарим скидку -30%**. Доступна поэтапная оплата. \n\n🎇Дарим доступ **к 20+ заданиям на взлом AD** на hackerlab.pro при записи на курс!\n\n**Старт курса 7 cентября**\n\n➡️️**Посмотреть программу и записаться **\n🪧**По вопросам** — @CodebyAcademyBot','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["hackerlab.pro"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:12:15.000Z','2026-08-26 09:12:22','2026-08-26 09:12:22');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_44baadbb-38b','tg_0','2364','39ba68c2c6057ef0fe127ca13fc7b297cad48d2d70d408302fbf12d48bee98c6',replace('**Я купил ноутбук за 6.000 рублей на AliExpress, да ещё и на ARM. Что за экзотику предлагают китайцы за 60$?**\n\nЗа 6 000 рублей на AliExpress всё ещё можно найти полноценный ARM-ноутбук. Внутри Allwinner A133P, 2 ГБ оперативной памяти, 32 ГБ eMMC и Android 13. \n\n⏺Железо слабое, тяжёлые сайты и игры идут с трудом, но сам ноутбук оказался вполне рабочим. Для Linux, моддинга, экспериментов и просто любителей необычного железа за 60 долларов это довольно интересная покупка.\n\n↪️ **Читать статью **\n\n**Бункер Хакера** | **Zeroday** | #Статья','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:12:58.000Z','2026-08-26 09:13:05','2026-08-26 09:13:05');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_0c4f9f5b-74d','tg_0','23245','c7b5288f499f31d42fa8bbbfe53c084c2ebe773ad29813e744006453ce25691f',replace('**ФНС доначисляет налоги ИТ-компаниям: как не потерять льготы в 2026 году**\n\n22 сентября заканчивается срок подтверждения аккредитации в Минцифры. Около трёх тысяч компаний рискуют её потерять — а вместе с ней и льготы по налогу на прибыль, страховым взносам и НДС. Именно после этой даты стоит ожидать новой волны выездных налоговых проверок.\n\nРазобрали пять оснований, по которым ФНС вправе доначислить налоги за три предыдущих периода сразу, какие ошибки компании допускают чаще всего и реально ли оспорить решение инспекции.\n\n**Читайте на АМ Live**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:34:58.000Z','2026-08-26 09:35:08','2026-08-26 09:35:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_16c0ffa1-26b','tg_0','3080','7c56bfc3108b1e463a0df363eef8de061793700206895d6217961d617c7ecfc0',replace('**tc filter: когда пакет меняется ещё до выхода из интерфейса**\n\nИногда маршрут выбран правильно, firewall ничего не блокирует, но трафик всё равно уходит не таким, каким его отправляет приложение.\n\nМежду сетевым стеком и интерфейсом пакет может пройти через `tc` — Traffic Control\n\n**Смотрим, есть ли вообще правила**\n\n```tc filter show dev eth0\n\nЕсли используется ingress:\n\ntc filter show dev eth0 ingress```\n\nНа современных системах правила могут быть привязаны к разным hook и chain, поэтому полезно сначала посмотреть всю конфигурацию интерфейса:\n\n```tc -s filter show dev eth0```\n\nНапример, можно обнаружить filter, который выполняет действие над пакетом ещё до его фактической отправки.\n\n**Что именно может делать filter**\n\nЧерез actions пакет можно перенаправить:\n\n```action mirred egress redirect dev ifb0```\n\nЗеркалировать на другой интерфейс:\n\n```action mirred egress mirror dev eth1```\n\nИли изменить его поля через `pedit.`\n\nНапример, переписать TTL или DSCP. Поэтому приложение может отправить обычный пакет, но на физический интерфейс он попадёт уже после обработки `tc.`\n\n**Смотрим actions подробнее**\n\n```tc -s filter show dev eth0 egress```\n\n`-s` добавляет статистику.\n\nЕсли у конкретного filter растут `Sent`, `bytes` или `packets`, правило реально обрабатывает трафик\nЭто полезнее простого просмотра конфигурации: сразу видно, какой filter участвует в обработке прямо сейчас\n\n**Почему это сложно заметить**\n\n`ip route get` покажет правильный интерфейс\n`iptables` или `nftables` могут быть пустыми\n\nНо пакет всё равно может:\n\n```eth0 → tc filter → redirect → ifb0```\n\nили:\n\n```application → tc filter → изменение полей → eth0```\n\nОсобенно часто это встречается на серверах с QoS, Kubernetes CNI, виртуализацией и BPF-программами.\n\n⚡️При странном поведении трафика полезно смотреть не только route и firewall, но и `tc qdisc`, `tc filter` и счётчики actions - пакет может изменить или направление, или параметры уже внутри сетевого стека Linux','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:35:16.000Z','2026-08-26 09:35:23','2026-08-26 09:35:23');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_68b48bfe-6f1','tg_0','1231','f1d12a6cf54570f2b5192d6f7ea4a89d89d4bc8877b860395e562e93d7186a8d','t.me/public_sec/1080','t.me/public_sec/1080','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:42:01.000Z','2026-08-26 09:42:08','2026-08-26 09:42:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_a3447c07-07c','tg_0','8065','785919985f1eabbed2fc24c9a4a2a44c4fec52325d0672a08f955ede2a3015cd',replace('🚨Cyber Alert ‼️\n\n🇸🇬Singapore - 𝗠𝗲𝗼𝘄𝗰𝗶𝗲𝘁𝘆𝟰𝟬𝟯 𝗖𝗹𝗮𝗶𝗺𝘀 𝗕𝗿𝗲𝗮𝗰𝗵 𝗼𝗳 𝗠𝗮𝗿𝗴𝗶𝗻 𝗪𝗵𝗲𝗲𝗹𝗲𝗿, 𝗦𝘄𝗶𝗳𝘁𝗹𝘆, 𝗮𝗻𝗱 𝗗𝗲𝗺𝗮𝗻𝗱\n\nThe Meowciety403 hacker group claims to have breached three Singapore-based companies, Margin Wheeler, Swiftly, and Demand, founded or co-founded by Kelvin Mun. \n\nAccording to the post, the allegedly compromised data includes over 5,400 candidate profiles/CVs, financial records, internal documents, SQL files, backend code, bank account details, and SWIFT codes.\n\nThreat actor: Meowciety403\nSector: Professional / Scientific / Technical\nData exposure (claimed): Not specified\nData type: Candidate profiles/CVs, financial records, internal documents, SQL files, backend code, bank account details and SWIFT codes\nObserved: Aug 26, 2026\nStatus: Pending verification\nESIX© (avg.): 5.27\n\nFull details and impact assessment on HackRisk.io','\n',char(10)),'Cyber Alert ‼️ 🇸🇬Singapore - 𝗠𝗲𝗼𝘄𝗰𝗶𝗲𝘁𝘆𝟰𝟬𝟯 𝗖𝗹𝗮𝗶𝗺𝘀 𝗕𝗿𝗲𝗮𝗰𝗵 𝗼𝗳 𝗠𝗮𝗿𝗴𝗶𝗻 𝗪𝗵𝗲𝗲𝗹𝗲𝗿, 𝗦𝘄𝗶𝗳𝘁𝗹𝘆, 𝗮𝗻𝗱 𝗗𝗲𝗺𝗮𝗻𝗱 The Meowciety403 hacker group claims to have breached three Singapore-based companies, Margin Wheeler, Swiftly, and Demand, founded or co-founded by Kelvin Mun. According to the post, the allegedly compromised data includes over 5,400 candidate profiles/CVs, financial records, internal documents, SQL files, backend code, bank account details, and SWIFT codes. Threat actor: Meowciety403 Sector: Professional / Scientific / Technical Data exposure','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["HackRisk.io"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T09:47:27.000Z','2026-08-26 09:47:33','2026-08-26 09:47:33');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_2927d5b7-4ac','tg_0','1594','f93d02da2565143999bfc73cfc528818e0ed83e60d005894b79ad3694f7e8a15',replace('**Disaster Recovery и Backup решают разные задачи, но их часто путают** 👁\n\nBackup сохраняет данные и восстанавливает их за часы, DR — восстанавливает работоспособность всей инфраструктуры за минуты. Если для критичных систем у вас есть только backup, вопрос по RTO (время до восстановления) скорее всего остается открытым.\n\n➡️**Evolution Disaster Recovery** от **Cloud․ru** закрывает именно эту часть – быстрого возобновления работы всей системы после серьезного сбоя.\n\n**Сервис устроен так:**\n▶️в ВМ устанавливается агент, который реплицирует данные на уровне ОС: без изменений в сети, гипервизоре или системах хранения;\n\n▶️при инциденте резервная копия инфраструктуры поднимается за минуты, а не разворачивается заново;\n\n▶️частоту репликации и сроки хранения можно настраивать под конкретные системы;\n\n▶️план восстановления можно протестировать в изолированном контуре, не затрагивая продакшен;\n\n▶️поддерживаются Windows, Debian, Ubuntu, RHEL и российские ОС — SberLinux и другие;\n\n▶️данные хранятся внутри защищенной платформы Cloud.ru с соответствием 152-ФЗ.\n\n\n**Подробнее о сервисе: **Evolution Disaster Recovery','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["Cloud.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:00:07.000Z','2026-08-26 10:00:14','2026-08-26 10:00:14');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_98f34df0-237','tg_0','1516','fad8b45674f7c289bc8f083467d66142b94907557d447191d1dfc3b0e0e52618',replace('👾 **Маяковский** — ИИ-помощник с руками: и помогатель, и агентов оркестратель.\n\nРутину — берет на себя. В лс — ответит. Картинку, документ — сделает.\n\nХарактер прилагается. Может и послать.','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:01:01.000Z','2026-08-26 10:01:08','2026-08-26 10:01:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_9a2d6236-d58','tg_0','15204','39ac992dbc9fe9c00c8913c55dbc323d3e9fa53b0d83bfdb0ea3bb44c909efe1',replace('Посмотрел поправки в 117-й приказ ФСТЭК, касающиеся вопросов ИБ искусственного интеллекта. Смотрел с точки зрения применения предлагаемых норм к различным типам ИИ - от обычного ML или локальной LLM (тут предлагаемые меры прям неплохо реализуются) до ИИ-агентов и мультиагентских систем, для которых приказ не очень хорош. Пока успел все свести в высокоуровневую табличку и... уехал в горы. Приеду, сведу все и отправлю регулятору предложения с правками. Надеюсь успею 🏔\n\nЗЫ. В проект приказа ФСТЭК по персданным тоже есть что добросить, но уже после возвращения. Буду надеяться, что сроки не пройдут 🗓\n\n#ии #регулирование','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:03:54.000Z','2026-08-26 10:04:01','2026-08-26 10:04:01');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_b4ce568e-59b','tg_0','588','198707cd8e9f43521fd5ffd255e5804305e3abc87798b49fce82006ff2ea97a1',replace('💡**Совет по Laravel**\n\nЗнаешь ли ты, что можно выбрасывать исключения условно всего в одну строку с помощью throw_if() — идеально для лаконичного кода в контроллерах и сервисах.','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:04:01.000Z','2026-08-26 10:04:08','2026-08-26 10:04:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_55ea7538-362','tg_0','4756','2aa6872fab0cfeefddc25e449f7483f5bf1b3a2239b1e3027e8de6cb8e18b44d',replace('**Представляем новый релиз Ankey IDM 1.11****✔️**\n \n__В новой версии__:\n \n1️⃣ **Появился отдельный модуль управления бизнес-процессами**. Встроенный BPMN-дизайнер переведён на новую версию. Появились подсказки по выражениям, копирование блоков между схемами, вызов transform-функций из процесса — это упрощает разработку и сокращает потребность во внешних интеграциях.\n \n2️⃣ **Переработаны инструменты формирования ролевой модели**. Обновлён интерфейс генерации ролей-кандидатов по стратегии «1 к 1» с экспортом/импортом в Excel. Автоматика сочетается с ручной экспертной доработкой, что ускоряет работу с большими объёмами данных.\n \n3️⃣ **Выделен отдельный интерфейс управления техническими учётными записями**. Реализованы создание типов, назначение владельцев и бенефициаров, активация, блокировка, смена пароля с настраиваемыми согласованиями. Технические учётные записи отображаются в карточке пользователя для целостного контекста.\n \n4️⃣ **Реализовано версионирование интеграций и работа с коннекторами**. Добавлены версионирование маппингов, моделирование и откат изменений. Улучшена обработка ошибок при установке коннекторов, появился экспорт конфигураций.\n \n5️⃣ **Объединены ручные и плановые кампании сертификации доступов**. Внедрены расписание, конструктор проверяемых объектов и отдельные процессы согласования для каждой кампании. Расширено внутреннее разграничение прав: системные роли управляют видимостью полей, вкладок и кнопок; добавлены шаблоны и привязка нескольких бизнес-ролей к одной системной.\n \n6️⃣ **Внедрены новые инструменты диагностики и эксплуатации**. В Ankey IDM 1.11 доступны мониторинг состояния сервисов, технический статус заявок с детализацией ошибок, структурированный вывод ошибок реконсиляции, фильтрация по кластерным нодам и привязка периодических задач к конкретной ноде.\n \n7️⃣ **Добавлена поддержка командно-проектной модели**. Новый раздел «Команды» позволяет создавать проектные команды и позиции, назначать руководителей и учитывать проектную иерархию в правилах автоматического назначения ролей — дополняя формальную оргструктуру.\n \n8️⃣ **Развиты отчётность, виджеты и интерфейс**. Внутренний сервис отчётов получил поддержку запуска по расписанию, групп получателей и отдельного интерфейса для планирования и просмотра уже сформированных отчётов. Для виджетов появились пользовательские подписи и вывод дополнительных параметров. Загрузка виджетов стала асинхронной, поэтому медленное получение данных одного из них не задерживает отображение остальных. Обновлён и ряд элементов интерфейса.\n \n9️⃣ **Продолжена оптимизация производительности и архитектуры**. Реализована очередь сообщений на Reactive Kafka с постепенным переводом наиболее нагруженных сервисов на новую схему обработки. Оптимизированы запросы ролей в визарде, правила автоматического назначения и массовое удаление назначений при удалении роли. Добавлен API для просмотра и управления фоновыми задачами, а конфигурациями микросервисов теперь можно управлять непосредственно из интерфейса Ankey IDM.\n__«Ankey IDM 1.11 продолжает развитие продукта в сторону более гибкого управления процессами и доступами, а также упрощения эксплуатации крупных и распределённых инсталляций. Основной акцент релиза сделан на управляемости: версиях процессов и интеграций, технических учётных записях, ролевой модели, диагностике и контроле работы компонентов комплекса», __— подчеркнул **Александр Давыдов**, менеджер продукта Ankey IDM компании «Газинформсервис».\n🔘 Узнать больше о продукте Ankey IDM можно здесь.\n\n#gis_новости #ankey_idm \n@gis_cybersec','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:05:02.000Z','2026-08-26 10:05:09','2026-08-26 10:05:09');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_c86483db-1e5','tg_0','3646','20ddaf39f1564b660d99c10d874554ec10089e2c9e6cd08847f7e07546235dc7',replace('😈 **О доверии к отечественным сертификатам и о проверке российских CT логов**\n\nВ комментариях недавней статье про фейл с ГОСТ сертификатом сайта ГосУслуг возникла **дискуссия о доверии к российским корневым сертификатам Минцифры и о рисках их установки** (в систему, в отдельный браузер, или риск использования Яндекс браузера, где они встроены).\n\nЗдесь вдаваться в подробности и повторять сказанное много раз не буду, включим только некое **саммари из основных тезисов для тех, кто не погружен в тему**:\n🔵Сами корневые сертификаты условнобезопасны\n🔵Если вы их поместили в доверенное хранилище, потенциально ваш трафик определенные лица могут расшифровать и даже подделать\n🔵Защититься от такой атаки сложно\n🔵Certificate Transparency логи и Яндекс браузер — неплохое решение в плане безопасности\n\n➡️**https://habr.com/ru/articles/1073480/**\n\n**#TLS**** ****#Certificate**** ****#Минцифры**** ****#Network**** ****#Browser**** // @****nsis**** // ****max.ru/nsis**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["habr.com","max.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:13:01.000Z','2026-08-26 10:13:11','2026-08-26 10:13:11');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_dcf7f0d4-2d6','tg_0','3609','bc55f93f26816bbced2395bd37d9717a8827dd8722bc0afbece33c8f5d880dea',replace('**🔥 В Go полностью переписали внутренности `sync.Map`\n**\nНачиная с Go 1.26, `sync.Map` официально работает на базе hash trie. Публичный API не изменился, но внутри теперь совсем другая структура.\n\nКак это устроено:\n\n* ключ хешируется в 64 бита\n* хеш разбивается на группы по 4 бита\n* каждый узел trie имеет до 16 потомков\n* lookup проходит по дереву максимум 16 уровней\n* структура снижает конкуренцию вокруг одного глобального lock\n\nНо `sync.Map` всё ещё не универсальная замена обычному `map`: в тестах статьи он потреблял примерно в 3-5 раз больше памяти.\n\nИспользовать его имеет смысл, когда значения в основном один раз записываются и много читаются или goroutine работают преимущественно с разными ключами. В остальных случаях `map` + `Mutex/RWMutex` часто проще и лучше.\n\nОчень подробный разбор реализации:\n\nhttps://victoriametrics.com/blog/go-sync-map-hash-trie/','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["sync.Map","victoriametrics.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:27:41.000Z','2026-08-26 10:27:48','2026-08-26 10:27:48');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_131d36d1-f48','tg_0','1781','3382cda7d2a4c6168055d0608ed64246cf09b808902298894a209f09189f992c',replace('📸 **Еще немного про отсылки**\n\nЭто партия наших работ из галереи CUB_3 и стенда BI.ZONE. \n\nВ комментах снова можно поугадывать к чему отсылают эти работы :)\n\nP. S. Фото и видео с конференции мы выложим в ближайшее время. Об этом дополнитеьно сообщим в постах.','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["BI.ZONE"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:37:01.000Z','2026-08-26 10:37:08','2026-08-26 10:37:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_c46cc1a8-e02','tg_0','3136','e0416df320545ee8e55584d9993ff81fd6367242ae15f54c6f821caea1f54b60',replace('Ну хз\n\nMy 8¢ Malware Analyst\n\nhttps://x.com/mrexodia/status/2090806161813405917','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:44:47.000Z','2026-08-26 10:44:54','2026-08-26 10:44:54');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_f30deeeb-ab9','tg_0','3940','89c3314813f6b626fc8417ab1d17b5d780c38b31a5bfdeff635ec534cc8dbf32',replace('🗣 **Как финансовым компаниям считать эффективность инвестиций в ИБ**\n\nВ новом выпуске Belyaev_Podcast «Финансы в ИБ» эксперты** **обсудили, как связать киберриски с экономикой бизнеса и не подменять устойчивость формальным соответствием требованиям.\n\n**Что еще в выпуске:**\n🛑 В финансовой ИБ нужно считать не только прямой ущерб, но и последствия простоев, неисполненных обязательств и потери доверия.\n🛑 CISO необходимы техническая база, управленческие навыки и понимание финансовой модели организации.\n🛑 SOC следует оценивать через скорость реакции, качество обработки алертов и способность ограничить распространение атаки.\n🛑 Культура безопасности создаёт дополнительный контур обнаружения: сотрудники могут раньше систем увидеть фишинг и аномалии.\n🛑 ИИ ускоряет защиту и одновременно расширяет возможности атакующих; критичной становится скорость обнаружения и локализации после проникновения.\n🛑 Формальное прохождение аудита не подтверждает готовность компании к реальной атаке.\n\nСсылки **на нашем сайте**\n\n😎  **Здесь о кибербезе**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T10:51:45.000Z','2026-08-26 10:51:51','2026-08-26 10:51:51');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_311e030f-f21','tg_0','1409','634b3be6aaab6d27f7d8e1a2fce6389dde407cf89205ff47e9a968fbec049f96',replace('📡 **RuView — система, которая «видит» людей через стены с помощью Wi‑Fi**\n\nRuView превращает обычные радиосигналы Wi‑Fi в бесконтактную систему наблюдения — без камер, микрофонов и носимых устройств.\n\nКогда человек двигается, дышит или просто находится в комнате, его тело изменяет распространение радиоволн. RuView считывает эти изменения через CSI — информацию о состоянии Wi‑Fi-канала — и анализирует их локально.\n\nЧто умеет проект:\n\n🔹 обнаруживать присутствие и движение людей;\n\n🔹 считать вошедших и вышедших;\n\n🔹 отслеживать дыхание и изменения пульса;\n\n🔹 распознавать падения и некоторые виды активности;\n\n🔹 контролировать сон и выявлять возможные признаки апноэ;\n\n🔹 работать в темноте и через стены на расстоянии примерно до пяти метров;\n\n🔹 передавать данные в Home Assistant, Apple Home, Google Home и Amazon Alexa.\n\nДля полноценной работы потребуется плата ESP32-S3 или другое оборудование, способное получать CSI. Один сенсор может стоить около $9. Обработка выполняется локально — облако и постоянное подключение к интернету не обязательны.\n\nПопробовать интерфейс без оборудования можно через Docker:\n\n```\ndocker pull ruvnet/wifi-densepose:latest\ndocker run -p 3000:3000 ruvnet/wifi-densepose:latest\n```\n\nПосле запуска панель будет доступна по адресу `http://localhost:3000`, но данные в этом режиме будут смоделированными.\n\nПроект выглядит впечатляюще, однако часть функций, особенно построение позы человека по Wi‑Fi, пока находится на экспериментальной стадии. Авторы честно указывают ограничения и публикуют результаты тестирования.\n\nhttps://github.com/ruvnet/ruview\n\n📲 **Мы в MAX**\n\n👉 @Githublib','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T11:04:34.000Z','2026-08-26 11:04:41','2026-08-26 11:04:41');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_8fe5dc47-e55','tg_0','1390','edf3d0b5e4cc7462a5b3cc5860b6c33e633ba9fc83fe6a347cb05c5d20218f82',replace('🦀 Rust target-директории становятся заметно меньше\n\nCargo тестирует в nightly новый подход, который сокращает дублирование метаданных в build-артефактах.\n\nПо результатам тестов размер `target` удалось уменьшить до 33%.\n\nОсобенно полезно для больших проектов и CI, где артефакты сборки быстро разрастаются.\n\nПодробнее:\nhttps://blog.rust-lang.org/inside-rust/2026/08/18/reducing-target-dir-size-on-nightly/','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["blog.rust-lang.org"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T11:04:44.000Z','2026-08-26 11:04:52','2026-08-26 11:04:52');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_74047fa9-7dc','tg_0','799','93d5a8179d6ae5c12fc02d41d590611403bd70b87d32a1569c92152cdef018f8',replace('**🔥 AI-агенты теперь можно безопаснее запускать прямо в GitHub Actions через Docker Sandboxes\n**\nGitHub Agentic Workflows получил поддержку `docker-sbx`. Агенту можно дать почти полноценную среду разработки - shell, `sudo`, Docker, базы и Testcontainers - но всё это выполняется внутри изолированной microVM.\n\nВ примере Docker агент:\n\n* запускает Java + PostgreSQL\n* сам находит баг\n* добавляет regression test\n* исправляет код\n* прогоняет тесты\n* открывает draft Pull Request\n\nУ sandbox собственные kernel, filesystem, network stack и приватный Docker daemon. При этом доступ наружу можно ограничить network allowlist и разрешёнными файлами.\n\nТо есть coding agent получает много свободы внутри песочницы, но не полный доступ к CI runner.\n\nhttps://www.docker.com/blog/running-ai-agents-in-github-actions-with-docker-sandboxes/','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.docker.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T11:08:08.000Z','2026-08-26 11:08:15','2026-08-26 11:08:15');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_7c891479-0e8','tg_0','8981','10b3fd980079d7b6ab5c822337e773c0bbba44efd5ca2bddc8d8034cb164f5fd',replace('Hmu if you verified and can help move slips Got a lot in stock, admins and  chats owners only\nYou get 30% every sale','\n',char(10)),'Hmu if you verified and can help move slips Got a lot in stock, admins and  chats owners only You get 30% every sale','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T11:08:21.000Z','2026-08-26 11:08:28','2026-08-26 11:08:28');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_cefedcc2-936','tg_0','2008','3d98d3127d81ff52b4624ef2b99ca11ff954d95596071120d827b9575531eb58','Ну как приятно то!',NULL,'ru',NULL,'QUARANTINED','2026-08-26T11:27:55.000Z','2026-08-26 11:28:03','2026-08-26 11:28:03');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_3e9be955-c3d','tg_0','2947','3baac4bc4c633a0891b5b4334171d867045d7425b28cb7da0ae6eee5f46e3d5a',replace('👩‍💻 **Pwning OWASP Juice Shop**\n\nОфициальное практическое руководство по исследованию защищенности, поиску уязвимостей и прохождению заданий в самом современном и популярном уязвимом веб-приложении OWASP Juice Shop.\n\nОфициальный спутник и практический учебник к проекту OWASP Juice Shop, предназначенный для пентестеров, специалистов по безопасности (AppSec), Bug Bounty охотников, веб-разработчиков, QA-инженеров и участников CTF-соревнований, желающих на практике освоить методы обнаружения и эксплуатации современных веб-уязвимостей.\n\n— Бьёрн Кимминич (создатель и лидер проекта OWASP Juice Shop) предлагает идеальный практический учебник, который **сочетает увлекательный игровой процесс (Gamification) со строгим обучением современным методам веб-пентеста**.\n\n🗄 Читать книгу – линк.\n🗄 Репозиторий на GitHub – линк.\n\n**//**** Не хакинг, а ИБ**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T11:30:01.000Z','2026-08-26 11:30:08','2026-08-26 11:30:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_2bd9f256-28f','tg_0','23246','c912295e6f874cdc0c76e46747af48c945fe874f86ae8958a52bcc5496dd3bdc',replace('🔥 **Сегодня в прямом эфире AM Live** с экспертами обсудили, как меняется подход к автоматизированной проверке защищённости и почему современным компаниям уже недостаточно разовых проверок безопасности.\n\nВ эфире поговорили:\n— чем автоматизированная проверка защищённости отличается от классического пентеста и сканирования уязвимостей;\n— какие инструменты помогают выявлять реальные риски;\n— как связать результаты разных проверок в единый процесс управления безопасностью;\n— какие ошибки чаще всего допускают при внедрении;\n— и какие подходы будут определять развитие автоматизированной проверки защищённости в ближайшие годы.\n\n**В эфире приняли участие:**\n\nМодератор: Вадим Шелест, Wildebrries & Russ\n\nСпикеры: \n\n⚡️ Данила Луцив, Security Vision\n⚡️ Давид Ордян, METASCAN\n⚡️Аскар Добряков, К2 Кибербезопасность\n⚡️ Ярослав Бабин, Positive Technologies \n⚡️ Максим Пятаков, CtrlHack\n⚡️ Денис Гамаюнов, SolidLab Group\n⚡️ Аркадий Никифоров, Бастион\n\n**Запись эфира уже доступна:**\n\n📺 VK 📺 YouTube 📺 RuTube \n\nСпасибо всем зрителям AM Live за участие, вопросы и активное обсуждение в чате!','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T11:31:45.000Z','2026-08-26 11:31:52','2026-08-26 11:31:52');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_c4ff9c6a-112','tg_0','23247','1e4ab8463004cbbb503bd525f44c00027ce6009af5244eeb93b6a57258bc69b5',replace('**Wildberries без анонса открыла мессенджер WB Chat для всех**\n\nWildberries без официального анонса открыла доступ к мессенджеру WB Chat. Аутентификация проходит через WB ID. Интерфейс предлагает знакомый набор: личные чаты, группы и каналы, которые можно создавать прямо с главного экрана.\n\n🔥 AM Live','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T11:41:49.000Z','2026-08-26 11:41:56','2026-08-26 11:41:56');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_066e4d70-85f','tg_0','1474','ddbaa5e4bf0c1f6692e28012735f83427a08cf84ca96a5143f0c0db6b56efede',replace('**AI-помощник для собеседований**\n\nInterview Boost AI помогает прямо во время интервью: отправляйте вопросы и скриншоты и получайте подсказки от **GPT, Claude, Grok и DeepSeek**.\n\n✓ работает **без VPN**\n✓ помогает с кодом и различными вопросами\n✓ окно приложения **не видно на собеседовании**\n✓ можно попробовать **бесплатно**\n\n👉 https://tglink.io/d393ff9b53227d\nerid: 2W5zFGBv2W5','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["tglink.io"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T12:00:28.000Z','2026-08-26 12:00:35','2026-08-26 12:00:35');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_68ac4ffc-a08','tg_0','1517','7aa231c91824dac8342a6ff41dc07acdcb3c45a7a0d7219daf540290d3f667e3',replace('Хороших разработчиков не заменить**\n\n**❤️**Only Hack**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T12:01:02.000Z','2026-08-26 12:01:10','2026-08-26 12:01:10');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_7bbfd919-e37','tg_0','4596','8f5a538d108e68f81a9b84e229936d4dd48ad53ec5ee5c05f9b82e68e50e023d',replace('🤒 **Почему готовый PoC не даёт root на встраиваемом железе**\n\nCVE-2016-5195 актуальна потому, что роутеры и камеры годами живут **на прошивке производителя без патчей**, а uname -a без истории обновлений не окончательный ответ.\n\nУспешная гонка только примитив записи: цепочка ломается на BusyBox без /bin/sh, на отсутствии SUID-целей или на том, что vDSO – код в памяти без файла на диске **требует адаптации под конкретную архитектуру и ABI.**\n\n— В данной статье мы разберем как декомпозировать PoC по этапам, что проверить в ядре и окружении до запуска и когда reverse shell можно заменить более простым payload''ом.\n\n**↘️** **SecurityLab**\n\n**☑️**** ****Записки Безопасника **\n\n⭐️ **max.ru/infosec_globe**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. CVEs: CVE-2016-5195 Full raw text preserved for provenance analysis.','ru','{"cves":["CVE-2016-5195"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["max.ru"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T12:32:06.000Z','2026-08-26 12:32:13','2026-08-26 12:32:13');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_9e096dea-0d2','tg_0','2317','4518a93e4ed3974738245b3cd83f588575dbd6751da0d7a790b71eb631f12892',replace('**Java-ловушка: **`.`** в формате числа не всегда означает точку\n**\nВ `DecimalFormat` шаблон вроде:\n\n```\n#,###.##\n```\n\nне гарантирует вывод `1,234.56`.\n\nСимволы зависят от locale:\n\n🇺🇸 US → `1,234.56`\n🇮🇹 Italy → `1.234,56`\n\nПоэтому если формат предназначен для конкретной страны, лучше задавать её явно:\n\n```\nDecimalFormatSymbols it =\n    new DecimalFormatSymbols(Locale.ITALY);\n\nDecimalFormat format =\n    new DecimalFormat("#,###.##", it);\n```\n\nИначе приложение может внезапно начать форматировать числа иначе просто потому, что JVM запустили с другой локалью.\n\nМелочь, которая особенно неприятно всплывает в деньгах, отчётах и CSV.','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["Locale.ITALY"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T12:40:08.000Z','2026-08-26 12:40:15','2026-08-26 12:40:15');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_5256bfb9-d7c','tg_0','837','365b66e73ae0a76b226d7274c6a7f0ab6efc10adbce61f883f5a4470230a60b4',replace('**Сутки со дня ****релиза****, статистика**\n\nЯ обещал делиться ходом челленджа максимально подробно, поэтому держите статистику:\n- Пользователей: 67\n- М / Ж: 54 / 4\n- Продаж: 0\n\nВсё бы ничего, но в боте был пробный тариф за 1р и даже его никто не попробовал. Оно и верно, главная фишка Атлетико — тренировки, а я трясу сходу деньги за них.\n\nЯ уже писал об одном из самых рабочих способов продвижения, поэтому решил применить его здесь. \n\nТеперь тренировки полностью бесплатны, а мне предстоит сделать упор на платный функционал, чтобы пользователи не только тренировались за спасибо, но ещё и оплачивали подписку.\n\nИ это абсолютно нормально — менять что-то, принимать радикальные меры. Пользуйтесь 🫶🏻','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T12:54:38.000Z','2026-08-26 12:54:45','2026-08-26 12:54:45');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_6da8e84d-187','tg_0','4227','86ae89a32c0efed5589cab84b7beab3ed3a0fdddfeb3c122a42e279527f91bc4',replace('**CIGRE 2026: протестирована защита IEC 104 с IEC 62351 и SVM**\n\nВ материалах CIGRE Session 2026 опубликована работа специалистов National Transmission Company South Africa по защите IEC 60870-5-104 и DNP3 поверх IP. Для IEC 104 авторы рассматривали IEC 62351-5 на прикладном уровне, TLS по IEC 62351-3 и расширения IEC 60870-5-7. Методика включала экспериментальные тесты и обучение модели SVM на данных со смоделированными spoofing, модификацией сообщений, replay и перехватом трафика.\n\nАвторы указывают, что лабораторный трафик не отражает весь шум реальной энергосистемы. Для применения на объекте модель предполагается переобучать на эксплуатационных данных с повторной настройкой параметров.\n\nИсточник: CIGRE, D2_12100_2026\n\nhttps://www.e-cigre.org/publications/detail/d2-12100-2026-securing-iec-60870-5-104-and-dnp3-over-ip-with-iec-62351-application-and-transport-layer-security.html','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["www.e-cigre.org","over-ip-with-iec-62351-application-and-transport-layer-security.html"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T12:56:09.000Z','2026-08-26 12:56:15','2026-08-26 12:56:15');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_fe951101-599','tg_0','1535','b6261a066f03b0edb09b160d2545296b0dacffa64cafb7b1d5bfa5a8e6db8fec',replace('**...каждый раз думаете вы, когда видите у себя в подписках очередной ИТ-канал с проходным контентом.**\n\n**«Кучевые АйТи»** вас точно не разочарует. Здесь нет нейрослопа — только редакционные материалы на тему облачных технологий. Ребята пишут о новых сервисах, влиянии ИИ на инфраструктуру и сети, тенденциях ИТ-рынка и берут интервью у экспертов ведущих ИТ-компаний.\n\n**Читайте в канале:**\n— Виртуальную машину с белым IP начинают брутфорсить через пару минут после поднятия. Как защитить только что арендованную VM?\n— Исследование: каждая 4-ая российская компания использует или пилотирует ИИ в облаке, и еще 18% планируют начать в ближайший год.\n— Половина 2026 год прошла — самое время спросить ИТ-компании, что происходит с бизнесом, какие задачи ставят клиенты, что изменилось. Читайте интервью Виталия Андриевского, СЕО Дата8.\n\n**Уверенно жмите и подписывайтесь на канал 👉 ****«Кучевые АйТи»**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T13:00:08.000Z','2026-08-26 13:00:15','2026-08-26 13:00:15');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_7983ba5f-815','tg_0','23248','edf4150465642ea263458209d7878c80a2f329eb23131edcedcdc6e7fe149a3a',replace('**ИИ в кибербезопасности: как меняются угрозы и средства защиты**\n\n90% зрителей AM Live отмечают: именно с помощью ИИ атакующие быстрее всего собирают данные о компании и сотрудниках. В эфире эксперты разбирали, как искусственный интеллект меняет расстановку сил между атакой и защитой, а участники поделились, куда они готовы пустить ИИ в своей работе, а куда пока нет.\n\nСамой опасной атакой с применением ИИ участники назвали фишинг и персонализированную социальную инженерию, а также автоматизированную разведку — по **65%** на каждую. При этом **90%** согласились, что именно в сборе данных о компании и сотрудниках ИИ помогает атакующим сильнее всего — это разрыв в восприятии: угрозу от разведки признают почти все, а вот в топ самых опасных атак она попадает наравне с более "заметными" векторами.\n\nНаиболее уязвимым звеном зрители считают бухгалтерию и финансы — **81%**, и внешних подрядчиков — **72%**. Разработчики и руководство делят третье место с **48%**, а служба ИТ, как ни странно, замыкает список — всего **14%**, хотя именно у ИТ обычно самые широкие доступы.\n\nС внедрением ИИ в защите ситуация неоднородная: **46%** респондентов пока вообще не используют ИИ в задачах ИБ. У тех, кто использует, лидирует реагирование на инциденты и подготовка отчётов — **54%**, а вот обнаружение фишинга и социальной инженерии с помощью ИИ не назвал ни один участник опроса — **0%**, при том что именно фишинг эксперты называли главной ИИ-угрозой.\n\nЗрители довольно охотно готовы доверить ИИ рутину: группировку алертов и поиск похожих инцидентов — **82%**, подготовку отчётов — **73%**. Но автоматическую блокировку учёток, токенов или хостов готовы доверить машине лишь **27%** — там, где цена ошибки слишком высока, доверие резко падает.\n\nПосле эфиров **47%** зрителей планируют развивать текущие ИИ-инструменты в ИБ, но у **24%** __это по-прежнему не приоритет__ — почти каждый четвёртый признаёт актуальность темы, но не готов действовать.\n\nИИ уже плотно встроен в рутинные задачи ИБ, но там, где решение необратимо, специалисты пока предпочитают оставлять последнее слово за человеком.\n\n__По данным опросов зрителей AM Live__ 🔥','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T13:02:24.000Z','2026-08-26 13:02:31','2026-08-26 13:02:31');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_bcd16de9-fae','tg_0','8068','9b308e2c18d9bb4357740ffd0e679bd22e86fc3b0b4e42c6cef48acaa8cbf2da',replace('🚨Cyber Alert ‼️\n\n🇺🇸USA - 𝗛𝗮𝗺𝗶𝗹𝘁𝗼𝗻 𝗖𝗼𝗺𝗽𝗮𝗻𝘆\n\nAiLock hacking group claims to have breached Hamilton Company, allegedly exfiltrating 40 TB of data.\n\nThreat actor: AiLock\nSector: Manufacturing\nData exposure (claimed): 40.0 TB\nData type: Not specified\nObserved: Aug 26, 2026\nStatus: Pending verification\nESIX©: 7.45\n\nFull details and impact assessment on HackRisk.io','\n',char(10)),'Cyber Alert ‼️ 🇺🇸USA - 𝗛𝗮𝗺𝗶𝗹𝘁𝗼𝗻 𝗖𝗼𝗺𝗽𝗮𝗻𝘆 AiLock hacking group claims to have breached Hamilton Company, allegedly exfiltrating 40 TB of data. Threat actor: AiLock Sector: Manufacturing Data exposure (claimed): 40.0 TB Data type: Not specified Observed: Aug 26, 2026 Status: Pending verification ESIX©: 7.45 Full details and impact assessment on HackRisk.io','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["HackRisk.io"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T13:05:35.000Z','2026-08-26 13:05:42','2026-08-26 13:05:42');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_55382f30-601','tg_0','8069','01f29558eb572614b1632b72b2aa41240a3d4f9c3b6e8aa3c16ed1b88e8ee138',replace('🚨Cyber Alert ‼️\n\n🇮🇹Italy - 𝗧𝗲𝗮𝗺𝗦𝘆𝘀𝘁𝗲𝗺\n\nTeamSystem disclosed a data breach affecting its “Contabilità in Cloud” accounting software after detecting unauthorised access on Aug 24, 2026. The company confirmed data exfiltration involving personal and contact information, IBAN bank account numbers and accounting transaction data, including payment descriptions, amounts and counterparties.\n\nThreat actor: Not specified\nSector: ICT\nData exposure (claimed): Not specified\nData type: Personal data, contact information, IBAN bank account numbers and accounting transaction data\nObserved: Aug 26, 2026\nStatus: Confirmed\nESIX©: 5.04\n\nFull details and impact assessment on HackRisk.io','\n',char(10)),'Cyber Alert ‼️ 🇮🇹Italy - 𝗧𝗲𝗮𝗺𝗦𝘆𝘀𝘁𝗲𝗺 TeamSystem disclosed a data breach affecting its “Contabilità in Cloud” accounting software after detecting unauthorised access on Aug 24, 2026. The company confirmed data exfiltration involving personal and contact information, IBAN bank account numbers and accounting transaction data, including payment descriptions, amounts and counterparties. Threat actor: Not specified Sector: ICT Data exposure (claimed): Not specified Data type: Personal data, contact information, IBAN bank account numbers and accounting transaction data Observed: Aug 26, 20','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["HackRisk.io"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T13:13:32.000Z','2026-08-26 13:13:38','2026-08-26 13:13:38');
