INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_c1f7434f-c7f','tg_0','14340','46061dce60324240132ac8958b1d3c82224cb65db83850f93c13296b6611c79a',replace('**Шестой бета-выпуск операционной системы Haiku R1**\n\nПосле двух лет разработки и спустя неделю после того как проекту исполнилось 25 лет опубликован шестой бета-выпуск  операционной системы Haiku R1. Изначально проект был создан как реакция на закрытие ОС BeOS и развивался под именем OpenBeOS, но был переименован в 2004 году из-за претензий, связанных с использованием в названии торговой марки BeOS. Для оценки работы нового выпуска подготовлено несколько загрузочных Live-образов (x86_64, x86 1.4 ГБ). Исходные тексты большей части ОС Haiku распространяются под свободной лицензией MIT, исключение составляют некоторые библиотеки, медиа-кодеки и компоненты, заимствованные из других проектов.\n\n Подробнее:\nhttps://opennet.ru/66149/\nhttps://opennet.me/66149/','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["opennet.ru","opennet.me"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T21:02:05.000Z','2026-08-26 21:02:12','2026-08-26 21:02:12');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_10134483-42b','tg_thehackernews','9900','9cbad427a3fa5db63e13081476b49ecd199b3af78b464fc00cf4403ea7f0c970',replace('🔥 FBI shuts down Chinese hacking platforms tied to intrusions at NASA, the Fed, and U.S. Senate.\n\nQScan exploited vulnerable IoT devices, while QTRouter hid attack traffic behind compromised devices, commercial proxies, and VPSs.\n\nHow it worked: https://thehackernews.com/2026/08/fbi-disrupts-china-linked-qtfy.html','\n',char(10)),'FBI shuts down Chinese hacking platforms tied to intrusions at NASA, the Fed, and U.S. Senate. QScan exploited vulnerable IoT devices, while QTRouter hid attack traffic behind compromised devices, commercial proxies, and VPSs. How it worked:','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["thehackernews.com","fbi-disrupts-china-linked-qtfy.html"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-26T16:42:52.000Z','2026-08-26 21:28:57','2026-08-26 21:28:57');
