INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_0f59afd2-78e','tg_0','9074','3d5ba174f412f098f5535513ec1fac1b5d381420872b8036b10cf914c9c0844f',replace('**NON-VBV CARDS TO APPLE PAY 🍎💳\nAND ALSO CASH APP 💰 & PAYPAL 💸 — ALL IN STOCK‼️\n\nIF YOU DON’T KNOW HOW IT WORKS AND WANT TO LEARN HOW TO MAKE MONEY THE EASY WAY 💼📈, HIT ME UP 📲\n\nI WILL WALK YOU THROUGH STEP BY STEP 🤝 — DON’T LET THIS OPPORTUNITY PASS YOU BY 🚀\n\nPM TO PURCHASE 👉 ****@jamalcooper**** 💯**','\n',char(10)),'**NON-VBV CARDS TO APPLE PAY AND ALSO CASH APP  & PAYPAL  — ALL IN STOCK‼️ IF YOU DON’T KNOW HOW IT WORKS AND WANT TO LEARN HOW TO MAKE MONEY THE EASY WAY , HIT ME UP I WILL WALK YOU THROUGH STEP BY STEP 🤝 — DON’T LET THIS OPPORTUNITY PASS YOU BY PM TO PURCHASE  ****@jamalcooper**** **','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-27T19:07:59.000Z','2026-08-27 19:08:06','2026-08-27 19:08:06');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_92596b14-bcf','tg_0','804','8bec01b0077e05d081afe00023dbe88a3f5dd4c5259ce0d9057abe3a0a920a2e',replace('**Новая брешь затронула все версии GNU Wget до 1.25.0**\n\nУязвимость CVE-2026-16599 (5,1) обнаружена в механизме FTP-аутентификации OPIE/S-KEY, который используется в GNU Wget. Проблема связана с тем, что Wget не проверял верхнюю границу порядкового номера, полученного от сервера при вычислении MD5-хеша.\n\nДля эксплуатации достаточно контролировать FTP-сервер или перехватывать трафик между сервером и клиентом. При передаче числа, близкого к максимальному значению целого типа, Wget может выполнить около 2,1 млрд операций MD5 подряд.\n\nРазработчики исправили ошибку 20 июня 2026 года, ограничив порядковый номер OPIE/S-KEY значением 9999. CERT Polska раскрыла подробности уязвимости 25 августа, согласовав сроки публикации с разработчиками утилиты.\n\n#gnu #wget #уязвимость #cve\n\n@ZerodayAlert','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. CVEs: CVE-2026-16599 Full raw text preserved for provenance analysis.','ru','{"cves":["CVE-2026-16599"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-27T19:12:42.000Z','2026-08-27 19:12:50','2026-08-27 19:12:50');
