INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_5669602d-c97','tg_0','3083','d0a13418a2c47fca960f6904dc318d40a817ed1e8b10167e775a4b95b4a263ba',replace('**Хочешь прокачать знания в DevOps?**\n\n**Но не знаешь где взять информацию и четкий план? ** \n\n 👍Рекомендуем **бесплатный мета-курс Devops Roadmap **- это расширенный чек-лист, который поможет вам сориентироваться в мире DevOps и стать крутым спецом.\n\n В мета-курсе перечислены все основные разделы и навыки, которыми должен обладать **DevOps инженер: от Linux до программирования. **\n\n✅Он будет полезен при подготовке к собеседованиям.\n\n📅А еще у автора есть крутые **практические курсы на собственной платформе и программа наставничества.** \n\n**Узнать больше**\n\n#реклама 16+\nplatform.lifeisfile.com\nО рекламодателе','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["platform.lifeisfile.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-27T22:20:18.000Z','2026-08-27 22:20:25','2026-08-27 22:20:25');
