INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_027032f3-d3e','tg_0','348','d994a9720c8d1569a30d83590d131b4abb1fc7abd2d60e43194942f7eb2c49a0',replace('Всем привет! Мой коллега Вячеслав Цепенников выступал на OFFZONE с докладом «Living off the Browser». Он наресерчил крутой функционал Direct Sockets внутри Chrome, который позволяет через Isolated Web Apps отправлять полноценные сетевые TCP/UDP-запросы. Путем нескольких бессонных ночей получилось внутрь Isolated Web App портировать большинство самых популярных тулз для пентеста! Теперь вы можете буквально ломать через браузер : )\n\nДемо:\nhttps://iwa-tools.pkilla.pw/\nСорцы:\nhttps://github.com/CICADA8-Research/iwa-tools','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["iwa-tools.pkilla.pw"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-27T22:54:04.000Z','2026-08-27 22:54:13','2026-08-27 22:54:13');
