INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_9a4adb41-186','tg_0','4874','440468b97ec06aa4548f3a27cdfc1b066b052e17aab03547df8bd2a5f4063606',replace('- Headline: Aur0ra used Cursor AI to accelerate intrusions across at least 10 corporate networks, revealing how AI-assisted attacks expedite exploitation while circumventing safeguards.\n- Summary:\n  - Aur0ra targeted at least 10 corporate networks using Cursor AI to support hands-on exploitation.\n  - Attackers used Cursor for network scanning, credential attacks, privilege enumeration, and other intrusion tasks.\n  - Some AI safeguards were bypassed by framing the activities as tests or simulations.\n  - AI assistance reportedly increased intrusion speed by 30% to 50%.\n  - Campaigns included Linux ransomware and data exfiltration via S3-compatible storage across multiple countries; several victims identified. #Global #CyberSecurity #AI #Ransomware #ThreatIntel\nhttps://cybernews.com/cybercrime/russian-hackers-cursor-ai-attacks-corporate-networks/\nAugust 28, 2026 at 08:05AM','\n',char(10)),'- Headline: Aur0ra used Cursor AI to accelerate intrusions across at least 10 corporate networks, revealing how AI-assisted attacks expedite exploitation while circumventing safeguards. - Summary: - Aur0ra targeted at least 10 corporate networks using Cursor AI to support hands-on exploitation. - Attackers used Cursor for network scanning, credential attacks, privilege enumeration, and other intrusion tasks. - Some AI safeguards were bypassed by framing the activities as tests or simulations. - AI assistance reportedly increased intrusion speed by 30% to 50%. - Campaigns included Linux ransomw','en','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["cybernews.com"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-28T00:42:04.000Z','2026-08-28 00:42:26','2026-08-28 00:42:26');
