INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_7e644009-20a','tg_0','805','342ad59d19253c084aa6b55719e937f14195b54cf4d2ad348267d3b85fd26d2d',replace('**Две уязвимости SharePoint позволяют обойти аутентификацию и выполнить код**\n\nСпециалисты Rapid7 обнаружили уязвимость CVE-2026-55040 (9,1) в механизме проверки JWT-токенов SharePoint. Несколько недочётов в проверке токенов позволяют неавторизованному пользователю сформировать поддельный JWT и действовать от имени любого пользователя, включая администратора сайта.\n\nПолученные права открывают путь ко второй уязвимости — CVE-2026-63520 (8,1) в Business Connectivity Services. Через загрузку специально подготовленной BDC-модели злоумышленник может заставить SharePoint выполнить произвольную команду с полномочиями служебной учётной записи сайта.\n\n18 августа CISA добавила CVE-2026-55040 в каталог известных эксплуатируемых уязвимостей после подтверждённых атак. Microsoft закрыла первую уязвимость июльским обновлением, а вторую — 11 августа, при этом VulnCheck оценивает число уязвимых серверов в интернете как минимум в 8500.\n\n#sharepoint #microsoft #уязвимость #cve\n\n@ZerodayAlert','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. CVEs: CVE-2026-55040, CVE-2026-63520 Full raw text preserved for provenance analysis.','ru','{"cves":["CVE-2026-55040","CVE-2026-63520"],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-28T03:04:01.000Z','2026-08-28 03:04:08','2026-08-28 03:04:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_3c9064b9-cc5','tg_0','8450','712a34d394f30cce526102391bf041c7d0e75d2499f35baf91d6b25bf2ae5db0',replace('**EP 10: Неудачные приключения государственного хакера\n**\nВ современной разведке правительства взламывают системы других правительств. В этом эпизоде вы пройдёте весь путь вместе с государственным хакером и увидите, как именно это делается.\n\nLink','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-28T04:09:21.000Z','2026-08-28 04:09:30','2026-08-28 04:09:30');
