INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_4c54a11d-687','tg_0','14345','ace568bab203f3ba9ff72ea7f884c4d8445aef3f4f49ce40004eb516211ccdc4',replace('**Обновление дистрибутива Ubuntu 26.04.1 LTS**\n\nКомпания Canonical представила первый корректирующий выпуск дистрибутива Ubuntu 26.04.1 LTS, в который включены  обновления для нескольких сотен пакетов, связанные с устранением уязвимостей и проблем, влияющих на стабильность. В новой версии также исправлены ошибки в инсталляторе и загрузчике. Релиз Ubuntu 26.04.1 ознаменовал прохождение базовой стабилизации LTS-выпуска - пользователям  прошлой LTS-ветки Ubuntu 24.04 теперь будет предложено осуществить обновление до ветки 26.04.\n\n Подробнее:\nhttps://opennet.ru/66156/\nhttps://opennet.me/66156/','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":["opennet.ru","opennet.me"],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-28T04:52:04.000Z','2026-08-28 04:52:11','2026-08-28 04:52:11');
