INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_69fa8c06-199','tg_0','1528','0170f5ecc381dc6ddf955cfd36600b34a25ed7f7fbf3060f6062d2b7ffbb7294',replace('Осторожно: остросоциальный мем\n\n❤️**Only Hack**','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-28T15:16:01.000Z','2026-08-28 15:16:08','2026-08-28 15:16:08');
INSERT INTO "source_messages" ("id","source_id","external_message_id","content_hash","raw_content","normalized_content","original_language","parsed_entities","status","published_at","created_at","updated_at") VALUES('msg_86d7a0a1-c92','tg_0','2366','cc5f4f7602b4f12fc85cf8b6f886ac4673d844e3c19032db85a380335be9e291',replace('**VPS-Audit - тул для быстрого аудита безопасности Linux-сервера**\n\nVPS-Audit - лёгкий Bash-скрипт без зависимостей, который за один запуск проверяет базовую безопасность и состояние VPS. SSH, файрволы, открытые порты, Fail2ban, неудачные попытки входа, SUID-файлы, активные сервисы - всё собирается в одном отчёте.\n\n⏺Заодно скрипт смотрит на ресурсы сервера: CPU, память, диск и активные соединения. Результаты сразу помечаются как PASS, WARN или FAIL, поэтому потенциальные проблемы не приходится выискивать вручную.\n\n💬** ****Ссылка на скачивание**\n\n**Бункер Хакера** | **Серверная Админа** | #Инструмент','\n',char(10)),'Raw threat telemetry captured in RU from Telegram Channel. Technical indicators extracted and correlated against threat database. Full raw text preserved for provenance analysis.','ru','{"cves":[],"ipv4s":[],"sha256s":[],"md5s":[],"domains":[],"ttps":[],"actors":[],"malware":[]}','SUCCEEDED','2026-08-28T15:19:18.000Z','2026-08-28 15:19:25','2026-08-28 15:19:25');
