INSERT INTO "vulnerabilities" ("id","cve_id","title","description","severity","cvss_score","cvss_vector","epss_score","is_exploited_in_wild","affected_vendor","affected_product","patch_url","published_at","created_at","updated_at") VALUES('vuln_cve_2026_62986','CVE-2026-62986','CVE-2026-62986 Security Advisory','CVE-2026-62986 OpenEXR is the reference implementation and specification for the EXR image file format, widely used in the motion picture industry. In versions 3.3.0 through 3.3.12 and 3.4.0 through 3.4.13, the PyOpenEXR Python bindings return stale heap data when reading a crafted deep scanline EXR that uses layer-prefixed RGB channels. With the default channel coalescing (separate_channels=False), the wrapper groups channels such as left.R, left.G, and left.B into a single RGB sample array, but the lane-offset calculation in PyPart::setDeepSliceData() only recognizes the exact unprefixed nam','HIGH',NULL,NULL,NULL,0,NULL,NULL,NULL,'2026-08-25T19:24:18.000Z','2026-08-25 19:24:59','2026-08-25 19:24:59');
INSERT INTO "vulnerabilities" ("id","cve_id","title","description","severity","cvss_score","cvss_vector","epss_score","is_exploited_in_wild","affected_vendor","affected_product","patch_url","published_at","created_at","updated_at") VALUES('vuln_cve_2026_80050','CVE-2026-80050','CVE-2026-80050 Security Advisory','CVE-2026-80050 ContiNew Admin fails to apply file-upload permission checks or file-type allowlist validation to multipart upload endpoints, allowing authenticated users to store files with arbitrary extensions. Attackers can initialize chunked uploads, send file parts, and complete uploads to leave arbitrary files in the storage backend accessible via web server URLs. @cveNotify','HIGH',NULL,NULL,NULL,0,NULL,NULL,NULL,'2026-08-25T19:25:04.000Z','2026-08-25 19:25:55','2026-08-25 19:25:55');
