INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_mitre_attack','MITRE ATT&CK® Enterprise Framework','The MITRE Corporation','MITRE Corporation','2024-04-23','v15.1','Apache-2.0','https://attack.mitre.org','framework','Adversary Tactics, Techniques, and Common Knowledge',0,'hash_kb_mitre_attack_2024-04-23','{"summary":"Globally-accessible knowledge base of adversary tactics and techniques based on real-world observations.","what_it_covers":"14 Tactics, 201 Techniques, 424 Sub-techniques across Initial Access, Execution, Persistence, Privilege Escalation, Defense Evasion, Credential Access, Discovery, Lateral Movement, Collection, Command and Control, Exfiltration, and Impact.","why_it_matters":{"ciso":"Provides standardized metrics for measuring defensive posture and mapping security investments to actual adversary behaviors.","soc":"Structures alert triage, threat detection rules, and behavioral telemetry against standardized technique IDs.","cti":"Serves as the lingua franca for adversary profiling, campaign tracking, and threat attribution.","incident_response":"Accelerates root cause analysis and scoping of attacker post-exploitation movement.","zayron_x":"Primary behavioral graph anchor for mapping observed telemetry, malware behavior, and threat actor profiles."},"relationships":{"related_threats":["Ransomware","Data Exfiltration","Living-off-the-Land"],"related_frameworks":["kb_mitre_d3fend","kb_nist_csf_2"],"related_regulations":["kb_reg_eu_nis2","kb_reg_eu_dora"]},"jurisdiction":"International","status":"ACTIVE","last_verified":"2026-08-25","tags":["MITRE","ATT&CK","TTP","Tactics","Techniques","Enterprise"]}','2026-08-25T16:09:58Z','2026-08-25T16:10:32Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_mitre_d3fend','MITRE D3FEND™ Defensive Countermeasure Matrix','MITRE Corporation','MITRE Corporation','2024-06-15','v0.12.0','CC-BY-4.0','https://d3fend.mitre.org','framework','Defensive Cyber Security Knowledge Graph',0,'hash_kb_mitre_d3fend_2024-06-15','{"summary":"A formal knowledge graph of cybersecurity countermeasure techniques that counteract offensive ATT&CK techniques.","what_it_covers":"Deceive, Model, Harden, Detect, Isolate, and Evict defensive technique hierarchies.","why_it_matters":{"ciso":"Enables engineering-led defense-in-depth architecture validation against known adversary vectors.","soc":"Provides precise defensive verification procedures when investigating specific technique alerts.","cti":"Enables CTI analysts to deliver actionable defensive recommendations directly linked to identified threat TTPs.","incident_response":"Guides precise containment and eradication maneuvers during active intrusions.","zayron_x":"Powers the automated defensive recommendation generator in canonical intelligence reports."},"relationships":{"related_frameworks":["kb_mitre_attack","kb_nist_csf_2"]},"jurisdiction":"International","status":"ACTIVE","last_verified":"2026-08-25","tags":["D3FEND","Defense","Countermeasures","Hardening","Detection"]}','2026-08-25T16:09:58Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_nist_csf_2','NIST Cybersecurity Framework (CSF) 2.0','National Institute of Standards and Technology','U.S. Department of Commerce','2024-02-26','2.0','Public Domain (U.S. Government)','https://csrc.nist.gov/pubs/cswp/29/the-nist-cybersecurity-framework-csf-20/final','framework','Enterprise Cybersecurity Governance & Risk Management',0,'hash_kb_nist_csf_2_2024-02-26','{"summary":"Guidance for industry, government agencies, and organizations to manage and reduce cybersecurity risks.","what_it_covers":"Six core functions: Govern (GV), Identify (ID), Protect (PR), Detect (DE), Respond (RS), and Recover (RC).","why_it_matters":{"ciso":"Universal benchmark for organizational cybersecurity strategy, audit compliance, and board-level risk reporting.","soc":"Structures SOC operational workflows across Detect, Respond, and Recover lifecycles.","cti":"Aligns threat intelligence prioritization with enterprise risk categories and critical assets.","incident_response":"Defines response planning, analysis, mitigation, and communications best practices.","zayron_x":"Provides strategic governance tagging for high-severity intelligence advisories."},"relationships":{"related_frameworks":["kb_mitre_attack","kb_nist_sp800_61r2"],"related_regulations":["kb_reg_us_circia","kb_reg_eu_nis2"]},"jurisdiction":"United States / Global","status":"ACTIVE","last_verified":"2026-08-25","tags":["NIST","CSF","Governance","RiskManagement","CoreFunctions"]}','2026-08-25T16:09:58Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_nist_sp800_61r2','NIST SP 800-61 Rev. 2: Computer Security Incident Handling Guide','Paul Cichonski, Tom Millar, Tim Grance, Karen Scarfone','NIST','2012-08-01','Rev. 2','Public Domain (U.S. Government)','https://csrc.nist.gov/pubs/sp/800/61/r2/final','standard','Incident Response Lifecycle & Forensics',0,'hash_kb_nist_sp800_61r2_2012-08-01','{"summary":"Authoritative handbook establishing the four-stage incident response lifecycle: Preparation; Detection & Analysis; Containment, Eradication & Recovery; and Post-Incident Activity.","what_it_covers":"Incident handling methodology, evidence preservation, chain of custody, containment strategies.","why_it_matters":{"ciso":"Ensures institutional preparedness and legally sound evidence handling during high-impact security breaches.","soc":"Defines playbook escalation criteria and severity tiering during telemetry analysis.","cti":"Provides the structured analytical timeline for reconstructing attacker intrusion campaigns.","incident_response":"Gold standard protocol for eradication verification and lessons-learned documentation.","zayron_x":"Forms the foundational structure for ZAYRON-X incident timeline reconstruction."},"relationships":{"related_frameworks":["kb_nist_csf_2","kb_mitre_attack"]},"jurisdiction":"United States / Global","status":"ACTIVE","last_verified":"2026-08-25","tags":["NIST","IncidentResponse","DFIR","Containment","Forensics"]}','2026-08-25T16:09:58Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_cisa_kev','CISA Known Exploited Vulnerabilities (KEV) Catalog','Cybersecurity and Infrastructure Security Agency (CISA)','U.S. Department of Homeland Security','2021-11-03','Live Catalog','Public Domain (U.S. Government)','https://www.cisa.gov/known-exploited-vulnerabilities-catalog','standard','Active In-the-Wild Vulnerability Exploitation',0,'hash_kb_cisa_kev_2021-11-03','{"summary":"The authoritative global register of CVEs confirmed to be actively weaponized in real-world attacks, mandated under Binding Operational Directive (BOD) 22-01.","what_it_covers":"CVE ID, Vendor/Project, Product, Vulnerability Name, Date Added, Short Description, Required Action, Due Date, Known Ransomware Campaign Use.","why_it_matters":{"ciso":"Enforces non-negotiable remediation deadlines for vulnerabilities with verified active threat vectors.","soc":"Drives immediate detection priority for exploit signatures matching KEV records.","cti":"Highest authority signal for converting theoretical vulnerabilities into confirmed critical threat alerts.","incident_response":"Immediate indicator of initial access vectors during enterprise perimeter compromises.","zayron_x":"Provides Tier 0 ground truth for validating CVE exploitation status in AI analyst reasoning."},"relationships":{"related_frameworks":["kb_nvd","kb_first_epss","kb_cvss"],"related_regulations":["kb_reg_us_circia","kb_reg_eu_nis2"]},"jurisdiction":"United States / Global","status":"ACTIVE","last_verified":"2026-08-25","tags":["CISA","KEV","Vulnerabilities","ActiveExploit","BOD22-01"]}','2026-08-25T16:09:58Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_nvd','National Vulnerability Database (NVD)','National Institute of Standards and Technology (NIST)','NIST','2005-01-01','API v2.0','Public Domain (U.S. Government)','https://nvd.nist.gov','standard','Common Vulnerabilities and Exposures Registry',0,'hash_kb_nvd_2005-01-01','{"summary":"The U.S. government repository of standards-based vulnerability management data represented using the Common Vulnerabilities and Exposures (CVE) system.","what_it_covers":"CVE descriptors, CVSS scores (v2, v3, v4), CPE dictionary, CWE taxonomy mappings.","why_it_matters":{"ciso":"Standard repository for enterprise asset inventory vulnerability scanning and SLA tracking.","soc":"Provides baseline CVSS severity metrics for incoming vulnerability notifications.","cti":"Foundational baseline for correlating vendor software flaws with threat actor tooling.","incident_response":"Supplies affected version ranges and vendor advisory reference links.","zayron_x":"Primary dictionary for CVE resolution and CWE weakness classification."},"relationships":{"related_frameworks":["kb_cisa_kev","kb_cvss","kb_cwe"]},"jurisdiction":"United States / Global","status":"ACTIVE","last_verified":"2026-08-25","tags":["NVD","CVE","Vulnerabilities","NIST","CPE"]}','2026-08-25T16:09:58Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_cvss','Common Vulnerability Scoring System (CVSS) v3.1 & v4.0','Forum of Incident Response and Security Teams (FIRST)','FIRST.Org, Inc.','2023-11-01','v4.0 / v3.1','FIRST Open Specification','https://www.first.org/cvss/','standard','Vulnerability Severity & Risk Assessment Standard',0,'hash_kb_cvss_2023-11-01','{"summary":"An open framework for communicating the characteristics and severity of software vulnerabilities via Base, Threat/Temporal, and Environmental metric groups.","what_it_covers":"Attack Vector (AV), Attack Complexity (AC), Privileges Required (PR), User Interaction (UI), Scope (S), Confidentiality (C), Integrity (I), Availability (A).","why_it_matters":{"ciso":"Standardized metric for prioritizing patch management SLAs across enterprise assets.","soc":"Establishes baseline alert thresholds for vulnerability-related security events.","cti":"Separates theoretical severity (CVSS) from real-world probability of exploitation (EPSS/KEV).","incident_response":"Assists in evaluating potential blast radius of exploited flaws.","zayron_x":"Provides deterministic scoring inputs for assessing technical vulnerability severity."},"relationships":{"related_frameworks":["kb_first_epss","kb_cisa_kev","kb_nvd"]},"jurisdiction":"International","status":"ACTIVE","last_verified":"2026-08-25","tags":["CVSS","FIRST","Severity","BaseScore","VulnerabilityScoring"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_first_epss','Exploit Prediction Scoring System (EPSS) v3','FIRST EPSS Special Interest Group','FIRST.Org, Inc.','2023-03-07','v3','FIRST Open Model','https://www.first.org/epss/','standard','Data-Driven Vulnerability Exploitation Probability',0,'hash_kb_first_epss_2023-03-07','{"summary":"A machine-learning model estimating the empirical probability (0.0 to 1.0) that a software vulnerability will be exploited in the wild within 30 days.","what_it_covers":"Daily probability scores and percentile rankings for all published CVEs.","why_it_matters":{"ciso":"Reduces remediation fatigue by focusing limited patching capacity on high-probability exploit targets.","soc":"Enhances vulnerability triage by prioritizing active weaponization risk over static CVSS scores.","cti":"Provides quantitative predictive intelligence regarding emerging exploitation trends.","incident_response":"Identifies high-likelihood target vectors during threat hunting operations.","zayron_x":"Core metric utilized in ZAYRON-X analytical confidence and urgency calculation."},"relationships":{"related_frameworks":["kb_cvss","kb_cisa_kev","kb_nvd"]},"jurisdiction":"International","status":"ACTIVE","last_verified":"2026-08-25","tags":["EPSS","FIRST","ExploitPrediction","Probability","VulnerabilityRisk"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_stix_taxii','STIX™ 2.1 & TAXII™ 2.1 Standards','OASIS Cyber Threat Intelligence (CTI) TC','OASIS Open','2021-01-25','STIX 2.1 / TAXII 2.1','OASIS Open Standard','https://oasis-open.github.io/cti-documentation/','standard','Structured Threat Information Expression & Trusted Exchange',0,'hash_kb_stix_taxii_2021-01-25','{"summary":"Structured language and transport protocol for exchanging cyber threat intelligence in machine-readable JSON format.","what_it_covers":"STIX Domain Objects (SDOs), STIX Relationship Objects (SROs), Threat Actor, Malware, Tool, Attack Pattern, Indicator, Sighting, Campaign.","why_it_matters":{"ciso":"Enables interoperability across SIEM, SOAR, TIP, and commercial intelligence providers.","soc":"Automates feed ingestion and IOC blocklist synchronization directly into boundary firewalls.","cti":"Standardized ontology for threat modeling, graph databases, and intelligence dissemination.","incident_response":"Facilitates standardized telemetry exchange with external ISACs and CERTs.","zayron_x":"Defines the underlying relational object graph for ZAYRON-X intelligence events and entities."},"relationships":{"related_frameworks":["kb_mitre_attack","kb_misp_core"]},"jurisdiction":"International","status":"ACTIVE","last_verified":"2026-08-25","tags":["STIX","TAXII","OASIS","CTI","MachineReadable","ThreatExchange"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_owasp_top10','OWASP Top 10 Application Security Risks','OWASP Foundation','OWASP Foundation','2021-09-24','2021 / 2025 Draft','CC-BY-SA-4.0','https://owasp.org/www-project-top-ten/','standard','Web Application & API Security Vulnerabilities',0,'hash_kb_owasp_top10_2021-09-24','{"summary":"Globally recognized standard awareness document for developers and web application security professionals representing the most critical security risks.","what_it_covers":"Broken Access Control, Cryptographic Failures, Injection, Insecure Design, Security Misconfiguration, Vulnerable and Outdated Components.","why_it_matters":{"ciso":"Foundational compliance benchmark for DevSecOps, SSDLC, and web application security audits.","soc":"Informs WAF signature tuning and API threat detection policies.","cti":"Contextualizes initial access techniques targeting exposed web applications.","incident_response":"Guides post-breach application log forensics and web shell discovery.","zayron_x":"Maps web application exploits to standardized OWASP categories in technical advisories."},"relationships":{"related_frameworks":["kb_cwe","kb_mitre_attack"]},"jurisdiction":"International","status":"ACTIVE","last_verified":"2026-08-25","tags":["OWASP","AppSec","WebSecurity","Injection","BrokenAccessControl"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_eu_nis2','EU Network and Information Security Directive (NIS2 Directive 2022/2555)','European Parliament and Council of the European Union','EUR-Lex (Official Journal of the European Union)','2022-12-27','Directive (EU) 2022/2555','Official EU Legal Text','https://eur-lex.europa.eu/eli/dir/2022/2555/oj','regulation','Critical Infrastructure Cybersecurity & Incident Reporting',0,'hash_kb_reg_eu_nis2_2022-12-27','{"summary":"EU-wide legislation establishing high common cybersecurity baseline obligations across essential and important entities, mandating 24-hour early warning incident notifications and senior management liability.","what_it_covers":"Risk management measures, supply chain security, 24h early warning notification, 72h incident notification, 1-month final report, corporate governance liability.","why_it_matters":{"ciso":"Imposes direct personal liability on corporate management and establishes strict 24-hour mandatory breach reporting.","soc":"Requires operational capabilities to detect, classify, and report significant incidents within 24 hours.","cti":"Demands proactive threat intelligence monitoring to fulfill continuous risk management obligations.","incident_response":"Mandates standardized reporting formats to national CSIRTs and regulatory authorities.","zayron_x":"Provides contextual regulatory tags when vulnerabilities impact critical EU sectors."},"relationships":{"related_frameworks":["kb_nist_csf_2","kb_mitre_attack"],"related_regulations":["kb_reg_eu_dora","kb_reg_eu_gdpr"]},"jurisdiction":"European Union","status":"ACTIVE","last_verified":"2026-08-25","tags":["NIS2","EU","Regulation","CriticalInfrastructure","IncidentReporting","24HourReporting"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:33Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_eu_dora','EU Digital Operational Resilience Act (DORA Regulation 2022/2554)','European Parliament and Council of the European Union','EUR-Lex','2022-12-27','Regulation (EU) 2022/2554','Official EU Legal Text','https://eur-lex.europa.eu/eli/reg/2022/2554/oj','regulation','Financial Sector Digital Operational Resilience & ICT Third-Party Risk',0,'hash_kb_reg_eu_dora_2022-12-27','{"summary":"Consolidated regulatory framework requiring financial entities (banks, insurers, investment firms) and critical ICT third-party providers to withstand, respond to, and recover from ICT-related disruptions.","what_it_covers":"ICT risk management, major ICT-related incident classification and reporting, digital operational resilience testing (TLPT/threat-led penetration testing), ICT third-party risk management.","why_it_matters":{"ciso":"Enforces rigorous third-party vendor oversight and mandatory threat-led penetration testing (TLPT).","soc":"Requires specialized incident classification matrices tailored to financial operations.","cti":"Mandates continuous threat modeling and intelligence sharing within authorized financial communities.","incident_response":"Establishes unified reporting templates to European Supervisory Authorities (EBA, EIOPA, ESMA).","zayron_x":"Assesses financial sector relevance and third-party risk during major CTI disclosures."},"relationships":{"related_frameworks":["kb_mitre_attack","kb_nist_csf_2"],"related_regulations":["kb_reg_eu_nis2","kb_reg_eu_gdpr"]},"jurisdiction":"European Union","status":"ACTIVE","last_verified":"2026-08-25","tags":["DORA","FinancialSector","EU","ThirdPartyRisk","Resilience","TLPT"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_eu_gdpr','EU General Data Protection Regulation (GDPR Regulation 2016/679)','European Parliament and Council of the European Union','EUR-Lex','2016-04-27','Regulation (EU) 2016/679','Official EU Legal Text','https://eur-lex.europa.eu/eli/reg/2016/679/oj','regulation','Personal Data Protection & 72-Hour Breach Notification',0,'hash_kb_reg_eu_gdpr_2016-04-27','{"summary":"The benchmark global standard for data privacy, mandating technical and organizational security measures (Article 32) and strict 72-hour breach notification to supervisory authorities (Article 33).","what_it_covers":"Data processing principles, data subject rights, security of processing (Article 32), 72-hour personal data breach notification (Article 33), penalties up to 20M EUR or 4% global turnover.","why_it_matters":{"ciso":"Massive financial exposure for data exfiltration incidents; mandates privacy-by-design architecture.","soc":"Demands immediate triage capability to determine if unauthorized access compromised personal identifiable information (PII).","cti":"Monitors ransomware data leak sites (DLS) for exfiltrated enterprise customer databases.","incident_response":"Drives forensic timeline precision required for regulatory notifications within 72 hours.","zayron_x":"Tags ransomware exfiltration events with GDPR breach risk assessment indicators."},"relationships":{"related_regulations":["kb_reg_eu_nis2","kb_reg_us_circia"]},"jurisdiction":"European Union / Global","status":"ACTIVE","last_verified":"2026-08-25","tags":["GDPR","Privacy","DataBreach","72HourNotification","PII","EU"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_eu_cra','EU Cyber Resilience Act (CRA)','European Commission / European Parliament','EUR-Lex','2024-03-12','Regulation (EU) 2024/2847','Official EU Legal Text','https://digital-strategy.ec.europa.eu/en/policies/cyber-resilience-act','regulation','Mandatory Cybersecurity Requirements for Hardware and Software Products',0,'hash_kb_reg_eu_cra_2024-03-12','{"summary":"Sets mandatory cybersecurity standards for all hardware and software products connected to the internet placed on the EU market, requiring Software Bill of Materials (SBOM) and 24-hour vulnerability reporting to ENISA.","what_it_covers":"Security by design, vulnerability handling processes, SBOM generation, 24h reporting of actively exploited vulnerabilities.","why_it_matters":{"ciso":"Requires complete product security lifecycle compliance and mandatory SBOM generation.","soc":"Integrates vulnerability disclosure intelligence directly with software supply chains.","cti":"Provides structured insights into zero-day disclosures reported directly to European authorities.","incident_response":"Enables rapid software component tracking during third-party library exploits.","zayron_x":"Evaluates software supply chain impact and SBOM components in vulnerability analyses."},"relationships":{"related_frameworks":["kb_cisa_kev","kb_owasp_top10"],"related_regulations":["kb_reg_eu_nis2"]},"jurisdiction":"European Union","status":"ACTIVE","last_verified":"2026-08-25","tags":["CRA","CyberResilienceAct","SBOM","ProductSecurity","HardwareSoftware","EU"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_us_circia','US Cyber Incident Reporting for Critical Infrastructure Act (CIRCIA)','Cybersecurity and Infrastructure Security Agency (CISA)','Federal Register / CISA','2022-03-15','CIRCIA Public Law 117-103','Public Domain (U.S. Government)','https://www.cisa.gov/circia','regulation','72-Hour Covered Cyber Incident & 24-Hour Ransom Payment Reporting',0,'hash_kb_reg_us_circia_2022-03-15','{"summary":"Requires covered entities in U.S. critical infrastructure sectors to report substantial cyber incidents to CISA within 72 hours and any ransom payments within 24 hours.","what_it_covers":"16 critical infrastructure sectors, 72h incident reporting, 24h ransomware payment reporting, information preservation mandates.","why_it_matters":{"ciso":"Enforces mandatory federal reporting deadlines with legal subpoena authority for non-compliance.","soc":"Requires strict categorization of ''substantial cyber incidents'' impacting operational capability.","cti":"Enhances bidirectional threat intelligence sharing between private infrastructure and federal defense.","incident_response":"Directly governs external communication and legal disclosure during ransomware crises.","zayron_x":"Highlights CIRCIA reporting triggers during active critical infrastructure intrusion events."},"relationships":{"related_frameworks":["kb_cisa_kev","kb_nist_csf_2"],"related_regulations":["kb_reg_eu_nis2"]},"jurisdiction":"United States","status":"ACTIVE","last_verified":"2026-08-25","tags":["CIRCIA","CISA","CriticalInfrastructure","RansomwareReporting","UnitedStates"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_us_hipaa','US HIPAA Security Rule (45 CFR Part 160 and Part 164)','U.S. Department of Health and Human Services (HHS)','HHS Office for Civil Rights','2003-02-20','45 CFR Parts 160, 164 Subparts A & C','Public Domain (U.S. Government)','https://www.hhs.gov/hipaa/for-professionals/security/index.html','regulation','Healthcare Electronic Protected Health Information (ePHI) Security',0,'hash_kb_reg_us_hipaa_2003-02-20','{"summary":"Establishes national standards to protect individuals'' electronic personal health information (ePHI) created, received, used, or maintained by covered healthcare entities.","what_it_covers":"Administrative safeguards, physical safeguards, technical safeguards (access control, audit controls, integrity, transmission security), breach notification rule.","why_it_matters":{"ciso":"Direct standard for healthcare cybersecurity architecture and regulatory liability.","soc":"Monitors unauthorized access attempts against Electronic Health Record (EHR) databases.","cti":"Tracks healthcare-targeted ransomware cartels (LockBit, BlackSuit, ALPHV).","incident_response":"Governs mandatory breach disclosures to HHS OCR and affected patient populations.","zayron_x":"Identifies healthcare sector implications in ransomware intelligence reports."},"relationships":{"related_regulations":["kb_reg_us_circia"]},"jurisdiction":"United States","status":"ACTIVE","last_verified":"2026-08-25","tags":["HIPAA","Healthcare","ePHI","HHS","DataProtection"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_uk_nis','UK Network and Information Systems (NIS) Regulations 2018','UK Department for Science, Innovation and Technology (DSIT)','legislation.gov.uk','2018-05-10','SI 2018/506 as amended','Open Government Licence v3.0','https://www.legislation.gov.uk/uksi/2018/506/contents','regulation','UK Operators of Essential Services (OES) & Relevant Digital Service Providers (RDSPs)',0,'hash_kb_reg_uk_nis_2018-05-10','{"summary":"Provides legal measures to boost the level of security for network and information systems for essential services (energy, transport, health, water, digital infrastructure) in the UK.","what_it_covers":"Security principles aligned with NCSC Cyber Assessment Framework (CAF), incident notification within 72 hours to designated competent authorities.","why_it_matters":{"ciso":"Governs compliance and Cyber Assessment Framework (CAF) audits for UK critical operations.","soc":"Structures telemetry monitoring against NCSC CAF baseline security indicators.","cti":"Integrates threat briefings provided by the UK National Cyber Security Centre (NCSC).","incident_response":"Establishes mandatory 72-hour reporting channels to UK competent authorities.","zayron_x":"Assesses UK jurisdictional impacts during critical infrastructure cyber attacks."},"relationships":{"related_frameworks":["kb_nist_csf_2"],"related_regulations":["kb_reg_eu_nis2"]},"jurisdiction":"United Kingdom","status":"ACTIVE","last_verified":"2026-08-25","tags":["UKNIS","NCSC","CAF","CriticalInfrastructure","UnitedKingdom"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_sg_cybersecurity_act','Singapore Cybersecurity Act 2018 (Act 9 of 2018 as amended)','Cyber Security Agency of Singapore (CSA)','Singapore Statutes Online','2018-03-12','Act 9 of 2018 / 2024 Amendment','Singapore Government Legal Text','https://sso.agc.gov.sg/Act/CA2018','regulation','Critical Information Infrastructure (CII) Protection & Licensing of Cybersecurity Service Providers',0,'hash_kb_reg_sg_cybersecurity_act_2018-03-12','{"summary":"Framework for the protection of Critical Information Infrastructure (CII) against cyber threats, authorizing the Commissioner of Cybersecurity to respond to national cybersecurity threats.","what_it_covers":"Designation of CIIs, mandatory technical audits, incident reporting within two hours of confirmation, licensing of penetration testing and SOC monitoring service providers.","why_it_matters":{"ciso":"Enforces strict two-hour notification timelines for incidents affecting Singapore CIIs.","soc":"Requires certified operational tooling and compliance with CSA cybersecurity codes of practice.","cti":"Monitors Asia-Pacific threat actor activity (Volt Typhoon, Lazarus, Mustang Panda).","incident_response":"Mandates immediate cooperation with SingCERT during national cyber incidents.","zayron_x":"Provides APAC regional regulatory context in technical intelligence advisories."},"relationships":{"related_regulations":["kb_reg_eu_nis2","kb_reg_us_circia"]},"jurisdiction":"Singapore / ASEAN","status":"ACTIVE","last_verified":"2026-08-25","tags":["Singapore","CSA","CybersecurityAct","CII","SingCERT","APAC"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_au_privacy_act','Australian Privacy Act 1988 & Notifiable Data Breaches (NDB) Scheme','Office of the Australian Information Commissioner (OAIC)','Federal Register of Legislation','1988-12-14','Act No. 119 of 1988 as amended','Commonwealth of Australia Legal Text','https://www.oaic.gov.au/privacy/privacy-legislation/the-privacy-act','regulation','Australian Privacy Principles & Mandatory Data Breach Notifications',0,'hash_kb_reg_au_privacy_act_1988-12-14','{"summary":"Governs the handling of personal information by Australian government agencies and private sector organizations, requiring notification of eligible data breaches to the OAIC.","what_it_covers":"13 Australian Privacy Principles (APPs), mandatory notification of eligible data breaches likely to result in serious harm, penalties up to AUD $50M.","why_it_matters":{"ciso":"Substantial statutory penalties under 2022 amendments; requires robust data governance.","soc":"Identifies data exfiltration triggers requiring immediate assessment under NDB guidelines.","cti":"Monitors Oceania adversary campaigns and dark web data auctions involving Australian entities.","incident_response":"Guides formal notification statements to OAIC and affected individuals.","zayron_x":"Provides Australian regulatory compliance mapping for data extortion incidents."},"relationships":{"related_regulations":["kb_reg_eu_gdpr"]},"jurisdiction":"Australia","status":"ACTIVE","last_verified":"2026-08-25","tags":["Australia","PrivacyAct","NDB","OAIC","DataBreach","Oceania"]}','2026-08-25T16:09:59Z','2026-08-25T16:10:34Z');
INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('kb_reg_sa_nca_ecc','Saudi Arabia NCA Essential Cybersecurity Controls (ECC-1:2018)','National Cybersecurity Authority (NCA)','NCA Kingdom of Saudi Arabia','2018-10-14','ECC-1:2018','Kingdom of Saudi Arabia NCA','https://nca.gov.sa/en/regulatory-documents/ecc','regulation','National Cybersecurity Controls for Government and Critical Organizations',0,'hash_kb_reg_sa_nca_ecc_2018-10-14','{"summary":"Mandatory baseline cybersecurity controls established by the Saudi National Cybersecurity Authority for all government entities and private organizations owning Critical National Infrastructure (CNI).","what_it_covers":"5 Cybersecurity Domains: Governance, Defense, Resilience, Third-Party/Cloud, Industrial Control Systems (ICS).","why_it_matters":{"ciso":"Mandatory compliance requirement for operating in the Kingdom of Saudi Arabia.","soc":"Enforces 24/7 continuous monitoring and localized logging requirements.","cti":"Provides strategic alignment with Middle Eastern threat landscape intelligence.","incident_response":"Establishes formal incident reporting protocols to the National Computer Emergency Response Center.","zayron_x":"Supports Middle Eastern and GCC regulatory intelligence assessment."},"relationships":{"related_frameworks":["kb_nist_csf_2"]},"jurisdiction":"Saudi Arabia / GCC","status":"ACTIVE","last_verified":"2026-08-25","tags":["NCA","SaudiArabia","ECC","MiddleEast","GCC","Compliance"]}','2026-08-25T16:10:00Z','2026-08-25T16:10:34Z');
