INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('org_shadowserver','The Shadowserver Foundation','The Shadowserver Foundation','The Shadowserver Foundation','2004-01-01','Live Scanning Feed','Public Benefit CTI','https://www.shadowserver.org','research_org','Internet-Wide Scanning, Botnet Tracking, Exposed Vulnerable Devices',1,'hash_org_shadowserver_2004-01-01','{"summary":"Non-profit security organization performing daily internet-wide scanning to measure vulnerable, compromised, and infected devices globally.","what_it_covers":"Exposed CVE counts, C2 sinkholing statistics, compromised infrastructure telemetry, DDoS botnets.","why_it_matters":{"ciso":"Provides macro-level empirical data on global enterprise attack surface exposure.","soc":"Enables verification of whether enterprise public IP ranges host exposed vulnerable appliances.","cti":"Authoritative empirical source for measuring actual victimology and exploitation scale.","incident_response":"Assists in identifying sinkholed C2 traffic originating from compromised networks.","zayron_x":"Supplies factual victim counts and scanning telemetry to corroborate CTI claims."},"relationships":{"related_frameworks":["kb_cisa_kev"]},"jurisdiction":"International","status":"ACTIVE","last_verified":"2026-08-25","tags":["Shadowserver","InternetScanning","Botnets","Telemetry","NonProfit"]}','2026-08-25T16:10:00Z','2026-08-25T16:10:35Z');
