INSERT INTO "knowledge_documents" ("id","title","author","publisher","publication_date","version","license","source_url","document_type","topic","authority_tier","content_hash","metadata","created_at","updated_at") VALUES('doc-nist-800-86','nist-sp-800-86',NULL,NULL,NULL,'Final','SOURCE_RECORDED','nist-sp-800-86','standard','nist-sp-800-86',0,'artifact-derived-nist-sp-800-86','{"processing_version": "phase6a-1"}','2026-08-28T13:24:57Z','2026-08-28T13:24:57Z');
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_idir_01','doc_ref_01_idir','Chapter 1: The Intelligence Lifecycle in IR',14,'The Cyber Threat Intelligence (CTI) lifecycle consists of five continuous phases: Planning and Direction, Collection, Processing and Exploitation, Analysis and Production, and Dissemination. Integrating CTI into Incident Response enables defenders to transition from reactive firefighting to hypothesis-driven threat hunting and proactive adversary disruption.','vec_chk_idir_01',1,120,'{"keyEntities":["Intelligence Lifecycle","Planning","Collection","Processing","Analysis","Dissemination"]}','2026-08-25T15:17:28Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_idir_02','doc_ref_01_idir','Chapter 3: The Diamond Model of Intrusion Analysis',45,'The Diamond Model of Intrusion Analysis formalizes every malicious activity into four core vertices: Adversary, Capability, Infrastructure, and Victim, connected by socio-political and technical axes. When analyzing telemetry, an analyst maps observed capabilities (e.g. Cobalt Strike, mimikatz) and infrastructure (e.g. C2 IP, dynamic DNS) to identify the adversary and protect the targeted victim sector.','vec_chk_idir_02',1,135,'{"keyEntities":["Diamond Model","Adversary","Capability","Infrastructure","Victim"]}','2026-08-25T15:17:31Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_idir_03','doc_ref_01_idir','Chapter 5: Confidence Estimation & Evidentiary Standard',92,'Analytical confidence in CTI must never be conflated with event severity. Confidence reflects the quality, diversity, and independence of supporting evidence, the degree of logical corroboration across multiple observation points, and the absence of contradictory signals. High severity with Low confidence indicates a potentially catastrophic claim that remains unverified and requires immediate evidence gathering.','vec_chk_idir_03',1,140,'{"keyEntities":["Analytical Confidence","Corroboration","Evidentiary Standards","ICD 203"]}','2026-08-25T15:17:32Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_idir_04','doc_ref_01_idir','Chapter 8: Strategic vs Operational vs Tactical Intelligence',158,'Threat intelligence operates at three distinct tiers: Tactical (atomic indicators such as IPs, domain names, file hashes consumed by firewalls and EDRs), Operational (adversary campaigns, attack paths, and MITRE ATT&CK TTPs utilized by SOC analysts and incident responders), and Strategic (geopolitical motives, executive risk exposure, and broad industry threat trends for leadership decision-making).','vec_chk_idir_04',1,130,'{"keyEntities":["Strategic Intelligence","Operational Intelligence","Tactical Intelligence","IOCs","TTPs"]}','2026-08-25T15:17:33Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_pma_01','doc_ref_02_pma','Chapter 1: Basic Static Analysis Techniques',22,'Basic static analysis inspects executable binaries without executing them. Key workflows include calculating cryptographic hashes (MD5, SHA256) for unique artifact identification, extracting ASCII/Unicode strings to discover hardcoded C2 domains, IP addresses, and registry keys, and parsing the Portable Executable (PE) Import Address Table (IAT) to identify critical Windows APIs such as VirtualAlloc, CreateRemoteThread, and InternetOpen.','vec_chk_pma_01',1,130,'{"keyEntities":["Static Analysis","PE Header","Imports","Exports","Strings","Hashes","SHA256"]}','2026-08-25T15:17:33Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_pma_02','doc_ref_02_pma','Chapter 3: Basic Dynamic Analysis & Sandboxing',58,'Basic dynamic analysis involves running malware in an isolated, monitored sandbox while observing behavioral modifications to the file system, registry, processes, and network interfaces. Analysts utilize Process Monitor (Procmon) to trace file/registry mutations, Regshot to detect persistence keys (e.g. Run/RunOnce), and Wireshark to intercept DNS queries, HTTP POST beacons, and TLS handshake characteristics.','vec_chk_pma_02',1,140,'{"keyEntities":["Dynamic Analysis","Process Monitor","Wireshark","Regshot","DNS Query","Beaconing"]}','2026-08-25T15:17:34Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_pma_03','doc_ref_02_pma','Chapter 11: Malware Persistence & Injection Mechanisms',240,'Advanced malware evades endpoint detection by injecting malicious code into legitimate processes (such as explorer.exe or svchost.exe). Techniques include classic DLL Injection (VirtualAllocEx -> WriteProcessMemory -> CreateRemoteThread), Process Hollowing (spawning a suspended legitimate binary, unmapping its section with NtUnmapViewOfSection, and writing malicious code), and Reflective DLL Loading entirely from memory.','vec_chk_pma_03',1,145,'{"keyEntities":["Process Injection","DLL Injection","Process Hollowing","Reflective DLL","Persistence"]}','2026-08-25T15:17:35Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_pma_04','doc_ref_02_pma','Chapter 14: Command and Control (C2) Protocols',310,'Adversary Command and Control (C2) channels employ diverse communications strategies including periodic jittered HTTP/HTTPS beacons, custom binary protocols over TCP/UDP, Domain Generation Algorithms (DGAs) to dynamically generate rendezvous domains, and Dead Drop Resolvers on legitimate platforms (Telegram, GitHub, Discord) to evade network perimeter defenses.','vec_chk_pma_04',1,125,'{"keyEntities":["Command and Control","Beaconing","Domain Generation Algorithm (DGA)","Dead Drop Resolver"]}','2026-08-25T15:17:36Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_pnsm_01','doc_ref_03_pnsm','Chapter 1: The Core Principles of NSM',12,'Network Security Monitoring (NSM) is the collection, analysis, and escalation of indications and warnings to detect and respond to intrusions. NSM relies on four empirical data types: Full Content Data (complete PCAPs), Session Data (NetFlow/IPFIX summary records), Statistical Data (metrics and baselines), and Alert Data (judgments generated by signature engines like Snort and Suricata).','vec_chk_pnsm_01',1,135,'{"keyEntities":["Network Security Monitoring","Full Content Data","Session Data","Statistical Data","Alert Data"]}','2026-08-25T15:17:37Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_pnsm_02','doc_ref_03_pnsm','Chapter 6: Investigating Alert & Session Data',134,'Session data provides transaction-level audit trails of network conversations without the storage overhead of full packet capture. Analyzing source/destination IPs, ports, byte volume ratios, and connection duration allows analysts to quickly identify beaconing cadences, internal lateral movement sweeps, and large-scale data exfiltration events.','vec_chk_pnsm_02',1,130,'{"keyEntities":["Session Data","NetFlow","Bro/Zeek","Connection Records","Data Exfiltration"]}','2026-08-25T15:17:38Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_amf_01','doc_ref_04_amf','Chapter 5: Memory Acquisition & Kernel Objects',85,'Volatile memory captures the true runtime state of an endpoint, revealing active malware that leaves zero disk footprint. By traversing the Windows kernel doubly-linked EPROCESS list and scanning for pool tags (psxview), forensic investigators detect Direct Kernel Object Manipulation (DKOM) where rootkits unhook their process from standard management APIs.','vec_chk_amf_01',1,130,'{"keyEntities":["Memory Forensics","EPROCESS","Volatility","Kernel Pool","DKOM"]}','2026-08-25T15:17:39Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_amf_02','doc_ref_04_amf','Chapter 12: Detecting In-Memory Code Injection',260,'In-memory code injection is identified by analyzing Virtual Address Descriptors (VAD) for memory regions allocated with PAGE_EXECUTE_READWRITE permissions that are not backed by an executable image on disk. Tools like Volatility malfind scan for memory pages containing executable permissions and extract raw assembly shellcode headers (e.g. MZ headers, NOP sleds, egg hunters).','vec_chk_amf_02',1,140,'{"keyEntities":["Malfind","PAGE_EXECUTE_READWRITE","In-Memory Injection","Shellcode Detection"]}','2026-08-25T15:17:40Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_mac_01','doc_ref_05_mac','Recipe 4-3: Deobfuscating XOR and Custom Encodings',112,'Malware authors routinely obfuscate configurations, embedded payloads, and C2 endpoints using single-byte XOR, multi-byte rolling XOR, RC4, or modified Base64 alphabet substitutions. Automated forensic deobfuscation scripts identify cryptographic key loops and extract plaintext configuration blocks containing secondary IP addresses, ports, and campaign IDs.','vec_chk_mac_01',1,125,'{"keyEntities":["Deobfuscation","XOR Decryption","RC4","Base64","Payload Extraction"]}','2026-08-25T15:17:40Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_tm_01','doc_ref_06_tm','Chapter 3: STRIDE Threat Modeling Framework',62,'The STRIDE mnemonic structures threat analysis into six threat categories: Spoofing (authenticity violation), Tampering (integrity violation), Repudiation (deniability of actions), Information Disclosure (confidentiality breach), Denial of Service (availability degradation), and Elevation of Privilege (authorization bypass). Analysts evaluate trust boundaries to identify where untrusted external data crosses into sensitive enterprise assets.','vec_chk_tm_01',1,140,'{"keyEntities":["STRIDE","Spoofing","Tampering","Repudiation","Information Disclosure","Denial of Service","Elevation of Privilege"]}','2026-08-25T15:17:41Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_tih_01','doc_ref_07_tih','Chapter 2: Tactical, Operational, and Strategic CTI',28,'Effective threat intelligence aligns collection with defender workflows. In vulnerability management, raw CVSS scores alone cause alert fatigue because fewer than 5% of published CVEs are ever exploited in the wild. Enriching CVE data with CTI indicators of active weaponization, dark web proof-of-concept availability, and APT campaign links reduces remediation backlogs by over 80%.','vec_chk_tih_01',1,130,'{"keyEntities":["Tactical CTI","Operational CTI","Strategic CTI","Vulnerability Prioritization"]}','2026-08-25T15:17:42Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_ansm_01','doc_ref_08_ansm','Chapter 4: Zeek (Bro) Telemetry & Transaction Logging',95,'Zeek provides semantic transaction logs of network application protocols. Conn.log records connection states (S0, SF, REJ), duration, and byte volume. DNS.log documents domain resolution lookups and response codes (NXDOMAIN bursts indicate DGA activity). SSL.log captures certificate subjects, issuers, JA3/JA3S TLS fingerprint hashes for identifying malicious C2 frameworks like Cobalt Strike and Metasploit.','vec_chk_ansm_01',1,135,'{"keyEntities":["Zeek","Conn.log","DNS.log","HTTP.log","SSL.log","Network Telemetry"]}','2026-08-25T15:17:43Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_nsm_adv_01','doc_ref_09_nsm_adv','Chapter 2: Defensible Network Architecture',44,'A defensible network architecture is monitored, controlled, minimized, and current. Critical sensor placement at network choke points (Internet egress, demilitarized zones, internal datacenter core) ensures complete visibility over ingress exploitation attempts, lateral movement pivot points, and outbound command-and-control communication.','vec_chk_nsm_adv_01',1,120,'{"keyEntities":["Defensible Architecture","Sensor Placement","Segmentation","Egress Filtering"]}','2026-08-25T15:17:44Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_hae_01','doc_ref_10_hae','Chapter 3: Buffer Overflows & Memory Corruption',118,'Stack-based buffer overflows occur when an application writes data past the allocated bounds of a stack buffer without validation (e.g. via strcpy, sprintf, gets). The overflowing data overwrites adjacent memory on the call stack, specifically replacing the saved frame pointer (EBP/RBP) and return address (EIP/RIP). When the function returns, execution redirects to attacker-supplied shellcode or Return-Oriented Programming (ROP) gadgets.','vec_chk_hae_01',1,145,'{"keyEntities":["Buffer Overflow","Stack Layout","EIP/RIP Control","Shellcode","ROP Chains","Memory Corruption"]}','2026-08-25T15:17:45Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_attack_01','doc_ref_11_mitre_attack','Tactics: Initial Access (TA0001) & Execution (TA0002)',NULL,'Initial Access (TA0001) encompasses techniques used to gain an initial foothold: Exploit Public-Facing Application (T1190), Phishing: Spearphishing Attachment/Link (T1566), Valid Accounts (T1078), and External Remote Services (T1133). Execution (TA0002) consists of adversary-controlled code execution techniques, notably Command and Scripting Interpreter (T1059: PowerShell, Windows Command Shell, Bash, Python), and User Execution (T1204: Malicious File/Link).','vec_chk_attack_01',0,155,'{"keyEntities":["MITRE ATT&CK","Initial Access (TA0001)","Execution (TA0002)","T1190","T1566","T1059"]}','2026-08-25T15:17:45Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_attack_02','doc_ref_11_mitre_attack','Tactics: Persistence (TA0003) & Privilege Escalation (TA0004)',NULL,'Persistence (TA0003) enables adversaries to maintain access across restarts and credential rotations: Boot/Logon Autostart Execution (T1547: Registry Run Keys / Startup Folder), Scheduled Task/Job (T1053), Create or Modify System Process (T1543: Windows Service, systemd). Privilege Escalation (TA0004) leverages Exploitation for Privilege Escalation (T1068), Access Token Manipulation (T1134), and Abuse Elevation Control Mechanism (T1548: UAC Bypass).','vec_chk_attack_02',0,150,'{"keyEntities":["MITRE ATT&CK","Persistence (TA0003)","Privilege Escalation (TA0004)","T1547","T1053","T1068"]}','2026-08-25T15:17:46Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_attack_03','doc_ref_11_mitre_attack','Tactics: Defense Evasion (TA0005) & Credential Access (TA0006)',NULL,'Defense Evasion (TA0005) involves methods to avoid detection: Process Injection (T1055: DLL Injection, Process Hollowing, Thread Execution Hijacking), Indicator Removal (T1070: Clear Windows Event Logs, File Deletion), Masquerading (T1036), and Obfuscated Files or Information (T1027). Credential Access (TA0006) extracts account names and passwords via OS Credential Dumping (T1003: LSASS Memory, NTDS.dit, SAM Database, DCSync), Kerberoasting (T1558.003), and Brute Force (T1110).','vec_chk_attack_03',0,160,'{"keyEntities":["MITRE ATT&CK","Defense Evasion (TA0005)","Credential Access (TA0006)","T1055","T1070","T1003"]}','2026-08-25T15:17:47Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_attack_04','doc_ref_11_mitre_attack','Tactics: Lateral Movement (TA0008) & Command and Control (TA0011)',NULL,'Lateral Movement (TA0008) allows adversaries to extend access across an enterprise: Remote Services (T1021: SMB/Windows Admin Shares, RDP, SSH, WinRM), and Software Deployment Tools (T1072). Command and Control (TA0011) maintains persistent communication: Application Layer Protocol (T1071: Web Protocols, DNS, Mail Protocols), Encrypted Channel (T1573: Asymmetric/Symmetric Cryptography), Dynamic Resolution (T1568: Fast Flux DNS, DGA), and Ingress Tool Transfer (T1105).','vec_chk_attack_04',0,155,'{"keyEntities":["MITRE ATT&CK","Lateral Movement (TA0008)","Command and Control (TA0011)","T1021","T1071","T1573"]}','2026-08-25T15:17:48Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_d3fend_01','doc_ref_12_mitre_d3fend','Core Defensive Tactics: Model, Harden, Detect, Isolate, Evict',NULL,'MITRE D3FEND provides a standardized knowledge graph of cybersecurity countermeasures directly mapped to counter ATT&CK techniques. Key defensive tactics include Model (asset mapping), Harden (application whitelisting, credential rotation), Detect (process lineage analysis, network traffic analysis, memory scraping verification), Isolate (network microsegmentation, process sandboxing), and Evict (process termination, credential invalidation, connection reset).','vec_chk_d3fend_01',0,145,'{"keyEntities":["MITRE D3FEND","Defensive Techniques","Process Analysis","Network Traffic Analysis","Eviction"]}','2026-08-25T15:17:49Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_nist_csf_01','doc_ref_13_nist_csf','The Six Core Functions of NIST CSF 2.0',NULL,'NIST CSF 2.0 establishes six core cybersecurity functions: Govern (GV: establishing cybersecurity risk management strategy, policy, and oversight), Identify (ID: inventorying physical/software assets, supply chain, and vulnerabilities), Protect (PR: access control, data security, platform baseline hardening), Detect (DE: continuous monitoring, anomaly detection), Respond (RS: incident triage, containment, mitigation), and Recover (RC: restoration, resilience improvement).','vec_chk_nist_csf_01',0,140,'{"keyEntities":["NIST CSF 2.0","Govern (GV)","Identify (ID)","Protect (PR)","Detect (DE)","Respond (RS)","Recover (RC)"]}','2026-08-25T15:17:49Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_nist_sp150_01','doc_ref_14_nist_sp800_150','Section 3: Trust Relationships, Provenance & Traffic Light Protocol (TLP)',NULL,'NIST SP 800-150 defines standards for cyber threat information sharing across trust circles. Information exchange utilizes the FIRST Traffic Light Protocol (TLP v2.0): TLP:RED (strictly for named individual recipients only), TLP:AMBER+STRICT / TLP:AMBER (limited to recipient organization and authorized clients), TLP:GREEN (shared within the recipient community and partners), and TLP:CLEAR (publicly releasable with zero sharing restrictions).','vec_chk_nist_sp150_01',0,145,'{"keyEntities":["NIST SP 800-150","TLP:RED","TLP:AMBER","TLP:GREEN","TLP:CLEAR","Information Sharing","Trust Circles"]}','2026-08-25T15:17:50Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_nist_sp61_01','doc_ref_15_nist_sp800_61','Section 3: The Incident Response Lifecycle',NULL,'NIST SP 800-61 Rev. 2 codifies the standard four-step incident handling lifecycle: 1. Preparation (tools, team readiness, defensible controls), 2. Detection and Analysis (triage, indicator correlation, scope determination, severity scoring), 3. Containment, Eradication, and Recovery (stopping attacker progression, removing artifacts and backdoors, validating clean systems), 4. Post-Incident Activity (documenting lessons learned, evidence retention, defensive tuning).','vec_chk_nist_sp61_01',0,140,'{"keyEntities":["NIST SP 800-61","Preparation","Detection & Analysis","Containment","Eradication","Recovery","Post-Incident"]}','2026-08-25T15:17:51Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_cisa_kev_01','doc_ref_16_cisa_kev','Criteria for In-The-Wild Exploitation & BOD 22-01 Directives',NULL,'CISA establishes three mandatory criteria for adding a vulnerability to the Known Exploited Vulnerabilities (KEV) Catalog: 1. The vulnerability has an assigned CVE ID; 2. There is reliable evidence that the vulnerability is being actively exploited in the wild (including use in ransomware attacks, nation-state APT campaigns, or unauthenticated remote code execution); 3. There is a clear action or vendor patch to mitigate the flaw.','vec_chk_cisa_kev_01',0,145,'{"keyEntities":["CISA KEV","Known Exploited Vulnerabilities","Binding Operational Directive 22-01","Active Exploitation","Ransomware Exploitation"]}','2026-08-25T15:17:52Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_nvd_cvss_01','doc_ref_17_nvd_cvss','CVSS v3.1 & v4.0 Base Metrics & Impact Calculations',NULL,'Common Vulnerability Scoring System (CVSS) Base Score reflects intrinsic technical characteristics. Metrics include Attack Vector (Network AV:N, Adjacent AV:A, Local AV:L, Physical AV:P), Attack Complexity (Low AC:L, High AC:H), Privileges Required (None PR:N, Low PR:L, High PR:H), User Interaction (None UI:N, Required UI:R), and Impact on Confidentiality, Integrity, Availability (None, Low, High). Qualitative ratings: Low (0.1-3.9), Medium (4.0-6.9), High (7.0-8.9), Critical (9.0-10.0).','vec_chk_nvd_cvss_01',0,155,'{"keyEntities":["CVSS v3.1","CVSS v4.0","Attack Vector (AV)","Attack Complexity (AC)","Privileges Required (PR)","User Interaction (UI)","Scope (S)","CIA Triad"]}','2026-08-25T15:17:53Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_first_epss_01','doc_ref_18_first_epss','EPSS Probability Scoring vs CVSS Severity',NULL,'The Exploit Prediction Scoring System (EPSS v3) estimates the empirical probability (from 0.0 to 1.0, representing 0% to 100%) that a software vulnerability will be exploited in the wild within the next 30 days. While CVSS measures severity (potential impact if exploited), EPSS measures threat likelihood based on real-world honeypot telemetry, public exploit availability, vendor advisory mentions, and historical weaponization patterns.','vec_chk_first_epss_01',0,145,'{"keyEntities":["FIRST EPSS","Exploit Prediction Scoring System","Probability","Percentile","Weaponization","Vulnerability Prioritization"]}','2026-08-25T15:17:54Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_oasis_stix_01','doc_ref_19_oasis_stix','Section 2: STIX Domain Objects (SDOs) and Relationship Objects (SROs)',NULL,'OASIS STIX 2.1 defines 18 STIX Domain Objects (SDOs) including Attack Pattern, Campaign, Course of Action, Grouping, Identity, Incident, Indicator, Infrastructure, Intrusion Set, Location, Malware, Malware Analysis, Note, Observed Data, Opinion, Report, Threat Actor, Tool, and Vulnerability. STIX Relationship Objects (SROs) such as "relationship" (uses, targets, indicates, exploits, attributed-to) and "sighting" connect SDOs into a computable threat graph.','vec_chk_oasis_stix_01',0,150,'{"keyEntities":["STIX 2.1","STIX Domain Objects (SDO)","STIX Relationship Objects (SRO)","Attack Pattern","Campaign","Malware","Threat Actor","Vulnerability"]}','2026-08-25T15:17:55Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('chk_owasp_llm_01','doc_ref_20_owasp_llm','Top Vulnerabilities: Prompt Injection (LLM01) & Insecure Output (LLM02)',NULL,'The OWASP Top 10 for LLM Applications catalogs critical security risks: LLM01: Prompt Injection (adversarial manipulation of model instructions via untrusted inputs or indirect RAG context), LLM02: Insecure Output Handling (executing unvalidated model output), LLM06: Sensitive Information Disclosure (leakage of PII, API keys, or system prompts), LLM08: Excessive Agency (granting autonomous execution permissions without human approval gates), and LLM09: Overreliance (blindly trusting hallucinations without claim-level evidence verification).','vec_chk_owasp_llm_01',0,155,'{"keyEntities":["OWASP Top 10 for LLM","LLM01: Prompt Injection","LLM02: Insecure Output Handling","LLM06: Sensitive Information Disclosure","LLM08: Excessive Agency","LLM09: Overreliance"]}','2026-08-25T15:17:55Z',NULL,NULL,NULL,NULL,NULL,NULL);
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-nist-800-150-p1-1','doc-nist-800-150',NULL,1,'NIST Special Publication 800-150 Guide to Cyber Threat Information Sharing Chris Johnson Lee Badger David Waltermire Julie Snyder Clem Skorupka This publication is available free of charge from: http://dx.doi.org/10.6028/NIST.SP.800-150 C O M P U T E R S E C U R I T Y',NULL,0,45,'{"source_id": "nist-sp-800-150", "content_hash": "89303DA25BEC571663D753A53C1961645E23372288B1855218416BDEA671897F"}','2026-08-28T13:24:57Z','nist-sp-800-150','Final',NULL,NULL,'89303DA25BEC571663D753A53C1961645E23372288B1855218416BDEA671897F','phase6a-1');
