INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-nist-800-150-p40-2','doc-nist-800-150',NULL,40,'Appendix C—Acronyms Selected acronyms used in the publication are defined below. ACL Access Control List ARP Address Resolution Protocol CCE Common Configuration Enumeration CIO Chief Information Officer CISO Chief Information Security Officer CPE Common Platform Enumeration CSIRT Computer Security Incident Response Team CUI Controlled Unclassified Information CVE Common Vulnerability Enumeration CVSS Common Vulnerability Scoring System CWE Common Weakness Enumeration DDoS Distributed Denial of Service DHCP Dynamic Host Configuration Protocol DIB Defense Industrial Base DNS Domain Name System FISMA Federal Information Security Modernization Act FTP File Transfer Protocol GLBA Gramm-Leach-Bliley Act HIPAA Health Information Portability and Accountability Act IP Internet Protocol IR Interagency Report or Internal Report ISAC Information Sharing and Analysis Center ISAO Information Sharing and Analysis Organization ISP Internet Service Provider IT Information Technology ITL Information Technology Laboratory MAC Media Access Control MOU Memorandum of Understanding NDA Non-Disclosure Agreement NIST National Institute of Standards and Technology NVD National Vulnerability Database OMB Office of Management and Budget PCAP Packet Capture PCI DSS Payment Card Industry Data Security Standard PII Personally Identifiable Information PSIRT Product Security Incident Response Team RSS Rich Site Summary or Really Simple Syndication SIEM Security Information and Event Management SLA Service Level Agreement SOX Sarbanes-Oxley Act SP Special Publication SQL Structured Query Language TCP Transmission Control Protocol TLP Traffic Light Protocol TTP Tactics, Techniques, and Procedures UDP User Datagram Protocol',NULL,0,223,'{"source_id": "nist-sp-800-150", "content_hash": "6F2DA3EE380802071A329197BB7A1E164A1096131831F0B9209ED45C45754C25"}','2026-08-28T13:24:57Z','nist-sp-800-150','Final',NULL,NULL,'6F2DA3EE380802071A329197BB7A1E164A1096131831F0B9209ED45C45754C25','phase6a-1');
