INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-nist-800-86-p4-1','doc-nist-800-86',NULL,4,'The Information Technology Laboratory (ITL) at the National Institute of Standards and Technology (NIST) promotes the U.S. economy and public welfare by providing technical leadership for the nations measurement and standards infrastructure. ITL develops tests, test methods, reference data, proof of concept implementations, and technical analysis to advance the development and productive use of information technology. ITLs responsibilities include the development of technical, physical, administrative, and management standards and guidelines for the cost-effective security and privacy of sensitive unclassified information in Federal computer systems. This Special Publication 800-series reports on ITLs research, guidance, and outreach efforts in computer security and its collaborative activities with industry, government, and academic organizations.',NULL,0,109,'{"source_id": "nist-sp-800-86", "content_hash": "396DD21023C3A4DFFB95B4D6BA487D895E47988B0FF9EC36333E52F9E35E2BA0"}','2026-08-28T13:24:57Z','nist-sp-800-86','Final',NULL,NULL,'396DD21023C3A4DFFB95B4D6BA487D895E47988B0FF9EC36333E52F9E35E2BA0','phase6a-1');
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-nist-800-86-p4-2','doc-nist-800-86',NULL,4,'Certain commercial entities, equipment, or materials may be identified in this document in order to describe an experimental procedure or concept adequately. Such identification is not intended to imply recommendation or endorsement by the National Institute of Standards and Technology, nor is it intended to imply that the entities, materials, or equipment are necessarily the best available for the purpose. National Institute of Standards and Technology Special Publication 800-86 Natl. Inst. Stand. Technol. Spec. Publ. 800-86, 121 pages (August 2006)',NULL,0,80,'{"source_id": "nist-sp-800-86", "content_hash": "23D1F24CFB8145006583E80D959992430AF0E0FBC2F811F954CAAABAFA51BA88"}','2026-08-28T13:24:57Z','nist-sp-800-86','Final',NULL,NULL,'23D1F24CFB8145006583E80D959992430AF0E0FBC2F811F954CAAABAFA51BA88','phase6a-1');
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-nist-800-86-p5-1','doc-nist-800-86',NULL,5,'The authors, Karen Kent and Tim Grance of the National Institute of Standards and Technology, and Suzanne Chevalier and Hung Dang of Booz Allen Hamilton, wish to thank their colleagues who reviewed drafts of this document and contributed to its technical content. The authors would particularly like to acknowledge Rick Ayers, Wayne Jansen, Peter Mell, and Murugiah Souppaya of NIST, and Adam Feldman, Mike Noblett, and Joseph Nusbaum of Booz Allen Hamilton, for their keen and insightful assistance throughout the development of the document. The authors would also like to express their thanks to security experts Susan Ballou (Office of Law Enforcement Standards), Brian Carrier (Purdue University), Eoghan Casey (Stroz Friedberg, LLC), Duane Crider (Microsoft), Kurt Dillard (Microsoft), Dean Farrington (Wells Fargo Bank), Jessica Reust (Stroz Friedberg, LLC), Marc Rogers (Purdue University), and Miles Tracy (U.S. Federal Reserve System), as well as representatives from the Department of State, for their particularly valuable comments and suggestions.',NULL,0,155,'{"source_id": "nist-sp-800-86", "content_hash": "4850A7D75330E72E4C12F4E3A20C0A2A9BFDB155BEDE612D16A04BE9EB900ECB"}','2026-08-28T13:24:57Z','nist-sp-800-86','Final',NULL,NULL,'4850A7D75330E72E4C12F4E3A20C0A2A9BFDB155BEDE612D16A04BE9EB900ECB','phase6a-1');
