INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-85','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2025-34291", "cwes": ["CWE-346"], "dateAdded": "2026-05-21", "dueDate": "2026-06-04", "knownRansomwareCampaignUse": "Unknown", "notes": "This vulnerability could affect an open-source component, third-party library, protocol, or proprietary implementation that could be used by different products. For more information, please see: https://github.com/langflow-ai/langflow ; https://github.com/langflow-ai/langflow/releases/tag/v1.9.3; https://github.com/langflow-ai/langflow/issues/11465#event-25774545848 ; https://nvd.nist.gov/vuln/detail/CVE-2025-34291", "product": "Langflow", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Langflow contains an origin validation error vulnerability in which an overly permissive CORS configuration combined with a refresh token cookie configured as SameSite=None allows a malicious webpage to perform cross-origin requests that include credentials and successfully call the refresh endpoint. This could allow the attacker to execute arbitrary code and achieve full system compromise via obtained tokens that permit access to authenticated endpoints.", "vendorProject": "Langflow", "vulnerabilityName": "Langflow Origin Validation Error Vulnerability"}',NULL,0,140,'{"source_id": "cisa-kev", "content_hash": "C09CB7C819F07E852DA3E5509F8F4D6BF83DC0F164239064DA2205F64C606D58"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2025-34291','C09CB7C819F07E852DA3E5509F8F4D6BF83DC0F164239064DA2205F64C606D58','phase6a-1');
