INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-189','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2026-23760", "cwes": ["CWE-288"], "dateAdded": "2026-01-26", "dueDate": "2026-02-16", "knownRansomwareCampaignUse": "Known", "notes": "https://www.smartertools.com/smartermail/release-notes/current ; https://nvd.nist.gov/vuln/detail/CVE-2026-23760", "product": "SmarterMail", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "SmarterTools SmarterMail contains an authentication bypass using an alternate path or channel vulnerability in the password reset API. The force-reset-password endpoint permits anonymous requests and fails to verify the existing password or a reset token when resetting system administrator accounts. This could allow an unauthenticated attacker to supply a target administrator username and a new password to reset the account, resulting in full administrative compromise of the SmarterMail instance.", "vendorProject": "SmarterTools", "vulnerabilityName": "SmarterTools SmarterMail Authentication Bypass Using an Alternate Path or Channel Vulnerability"}',NULL,0,124,'{"source_id": "cisa-kev", "content_hash": "DDF794F34C8C3CAFFF44C6E6E988DC965F11EE4C49FD8D732557D03ACD5FAB18"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2026-23760','DDF794F34C8C3CAFFF44C6E6E988DC965F11EE4C49FD8D732557D03ACD5FAB18','phase6a-1');
