INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-210','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2025-43529", "cwes": ["CWE-416"], "dateAdded": "2025-12-15", "dueDate": "2026-01-05", "knownRansomwareCampaignUse": "Unknown", "notes": "https://support.apple.com/en-us/125884 ; https://support.apple.com/en-us/125892 ; https://support.apple.com/en-us/125885 ; https://support.apple.com/en-us/125886 ; https://support.apple.com/en-us/125889 ; https://nvd.nist.gov/vuln/detail/CVE-2025-43529", "product": "Multiple Products", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Apple iOS, iPadOS, macOS, and other Apple products contain a use-after-free vulnerability in WebKit. Processing maliciously crafted web content may lead to memory corruption. This vulnerability could impact HTML parsers that use WebKit, including but not limited to Apple Safari and non-Apple products which rely on WebKit for HTML processing.", "vendorProject": "Apple", "vulnerabilityName": "Apple Multiple Products Use-After-Free WebKit Vulnerability"}',NULL,0,109,'{"source_id": "cisa-kev", "content_hash": "A76FD6468352024F4B67BD48A384D5AE9842780F92F18A7293B4BCD0EAF4F264"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2025-43529','A76FD6468352024F4B67BD48A384D5AE9842780F92F18A7293B4BCD0EAF4F264','phase6a-1');
