INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-251','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2025-27915", "cwes": ["CWE-79"], "dateAdded": "2025-10-07", "dueDate": "2025-10-28", "knownRansomwareCampaignUse": "Unknown", "notes": "https://wiki.zimbra.com/wiki/Security_Center ; https://nvd.nist.gov/vuln/detail/CVE-2025-27915", "product": "Zimbra Collaboration Suite (ZCS)", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "Synacor Zimbra Collaboration Suite (ZCS) contains a cross-site scripting vulnerability that exists in the Classic Web Client due to insufficient sanitization of HTML content in ICS files. When a user views an e-mail message containing a malicious ICS entry, its embedded JavaScript executes via an ontoggle event inside a tag. This allows an attacker to run arbitrary JavaScript within the victim''s session, potentially leading to unauthorized actions such as setting e-mail filters to redirect messages to an attacker-controlled address. As a result, an attacker can perform unauthorized actions on the victim''s account, including e-mail redirection and data exfiltration.", "vendorProject": "Synacor", "vulnerabilityName": "Synacor Zimbra Collaboration Suite (ZCS) Cross-site Scripting Vulnerability"}',NULL,0,153,'{"source_id": "cisa-kev", "content_hash": "9114C0E500CEC2D9BE1AF52625181FB16C881FF9762A3778C289347FA9D9A4D0"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2025-27915','9114C0E500CEC2D9BE1AF52625181FB16C881FF9762A3778C289347FA9D9A4D0','phase6a-1');
