INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-302','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2025-49704", "cwes": ["CWE-94"], "dateAdded": "2025-07-22", "dueDate": "2025-07-23", "knownRansomwareCampaignUse": "Known", "notes": "CISA Mitigation Instructions: https://www.cisa.gov/news-events/alerts/2025/07/20/microsoft-releases-guidance-exploitation-sharepoint-vulnerability-cve-2025-53770; https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/ ; https://msrc.microsoft.com/update-guide/vulnerability/CVE-2025-49704 ; https://nvd.nist.gov/vuln/detail/CVE-2025-49704", "product": "SharePoint", "requiredAction": "Disconnect public-facing versions of SharePoint Server that have reached their end-of-life (EOL) or end-of-service (EOS) to include SharePoint Server 2013 and earlier versions. For supported versions, please follow the mitigations according to CISA (URL listed below in Notes) and vendor instructions (URL listed below in Notes). Adhere to the applicable BOD 22-01 guidance for cloud services or discontinue use of the product if mitigations are not available.", "shortDescription": "Microsoft SharePoint contains a code injection vulnerability that could allow an authorized attacker to execute code over a network. This vulnerability could be chained with CVE-2025-49706. CVE-2025-53770 is a patch bypass for CVE-2025-49704, and the updates for CVE-2025-53770 include more robust protection than those for CVE-2025-49704.", "vendorProject": "Microsoft", "vulnerabilityName": "Microsoft SharePoint Code Injection Vulnerability"}',NULL,0,145,'{"source_id": "cisa-kev", "content_hash": "DFC281A8C2ECFB310BD442CB8D010D7139633E16A73677D872B6C679EB107C13"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2025-49704','DFC281A8C2ECFB310BD442CB8D010D7139633E16A73677D872B6C679EB107C13','phase6a-1');
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-303','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2025-49706", "cwes": ["CWE-287"], "dateAdded": "2025-07-22", "dueDate": "2025-07-23", "knownRansomwareCampaignUse": "Known", "notes": "CISA Mitigation Instructions: https://www.cisa.gov/news-events/alerts/2025/07/20/microsoft-releases-guidance-exploitation-sharepoint-vulnerability-cve-2025-53770 ; https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/ ; https://msrc.microsoft.com/update-guide/vulnerability/CVE-2025-49706 ; https://nvd.nist.gov/vuln/detail/CVE-2025-49706", "product": "SharePoint", "requiredAction": "Disconnect public-facing versions of SharePoint Server that have reached their end-of-life (EOL) or end-of-service (EOS) to include SharePoint Server 2013 and earlier versions. For supported versions, please follow the mitigations according to CISA (URL listed below in Notes) and vendor instructions (URL listed below in Notes). Adhere to the applicable BOD 22-01 guidance for cloud services or discontinue use of the product if mitigations are not available.", "shortDescription": "Microsoft SharePoint contains an improper authentication vulnerability that allows an authorized attacker to perform spoofing over a network. Successfully exploitation could allow an attacker to view sensitive information and make some changes to disclosed information. This vulnerability could be chained with CVE-2025-49704. CVE-2025-53771 is a patch bypass for CVE-2025-49706, and the updates for CVE-2025-53771 include more robust protection than those for CVE-2025-49706.", "vendorProject": "Microsoft", "vulnerabilityName": "Microsoft SharePoint Improper Authentication Vulnerability"}',NULL,0,162,'{"source_id": "cisa-kev", "content_hash": "644682A15A7B38D3807DDBD6558FA664772F2141AC83BF08CAD53553E48B710D"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2025-49706','644682A15A7B38D3807DDBD6558FA664772F2141AC83BF08CAD53553E48B710D','phase6a-1');
INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-304','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2025-53770", "cwes": ["CWE-502"], "dateAdded": "2025-07-20", "dueDate": "2025-07-21", "knownRansomwareCampaignUse": "Known", "notes": "CISA Mitigation Instructions: https://www.cisa.gov/news-events/alerts/2025/07/20/microsoft-releases-guidance-exploitation-sharepoint-vulnerability-cve-2025-53770; https://www.microsoft.com/en-us/security/blog/2025/07/22/disrupting-active-exploitation-of-on-premises-sharepoint-vulnerabilities/ ; https://msrc.microsoft.com/update-guide/vulnerability/CVE-2025-53770 ; https://nvd.nist.gov/vuln/detail/CVE-2025-53770", "product": "SharePoint", "requiredAction": "Disconnect public-facing versions of SharePoint Server that have reached their end-of-life (EOL) or end-of-service (EOS) to include SharePoint Server 2013 and earlier versions. For supported versions, please follow the mitigations according to CISA (URL listed below in Notes) and vendor instructions (URL listed below in Notes). Adhere to the applicable BOD 22-01 guidance for cloud services or discontinue use of the product if mitigations are not available.", "shortDescription": "Microsoft SharePoint Server on-premises contains a deserialization of untrusted data vulnerability that could allow an unauthorized attacker to execute code over a network. This vulnerability could be chained with CVE-2025-53771. CVE-2025-53770 is a patch bypass for CVE-2025-49704, and the updates for CVE-2025-53770 include more robust protection than those for CVE-2025-49704.", "vendorProject": "Microsoft", "vulnerabilityName": "Microsoft SharePoint Deserialization of Untrusted Data Vulnerability"}',NULL,0,151,'{"source_id": "cisa-kev", "content_hash": "C4B7F74FAC46C5EDDB842C2E47D917D855450B6C147F40F55B