INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-317','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2024-0769", "cwes": ["CWE-22"], "dateAdded": "2025-06-25", "dueDate": "2025-07-16", "knownRansomwareCampaignUse": "Unknown", "notes": "https://supportannouncement.us.dlink.com/announcement/publication.aspx?name=SAP10371 ; https://nvd.nist.gov/vuln/detail/CVE-2024-0769", "product": "DIR-859 Router", "requiredAction": "Apply mitigations per vendor instructions, follow applicable BOD 22-01 guidance for cloud services, or discontinue use of the product if mitigations are unavailable.", "shortDescription": "D-Link DIR-859 routers contain a path traversal vulnerability in the file /hedwig.cgi of the component HTTP POST Request Handler. Manipulation of the argument service with the input ../../../../htdocs/webinc/getcfg/DHCPS6.BRIDGE-1.xml allows for the leakage of session data potentially enabling privilege escalation and unauthorized control of the device. This vulnerability affects legacy D-Link products. All associated hardware revisions have reached their end-of-life (EOL) or end-of-service (EOS) life cycle and should be retired and replaced per vendor instructions.", "vendorProject": "D-Link", "vulnerabilityName": " D-Link DIR-859 Router Path Traversal Vulnerability"}',NULL,0,126,'{"source_id": "cisa-kev", "content_hash": "7B03DE51AB0F6BC682045712353A8F5D2185F11046A4F61028D3C11A51FDECF2"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2024-0769','7B03DE51AB0F6BC682045712353A8F5D2185F11046A4F61028D3C11A51FDECF2','phase6a-1');
