INSERT INTO "knowledge_chunks" ("id","document_id","section","page","text","embedding_id","authority_tier","token_count","metadata","created_at","source_id","version","chapter","subsection","content_hash","processing_version") VALUES('doc-cisa-kev-record-665','doc-cisa-kev','KEV record',NULL,'{"cveID": "CVE-2023-20273", "cwes": ["CWE-78"], "dateAdded": "2023-10-23", "dueDate": "2023-10-27", "knownRansomwareCampaignUse": "Unknown", "notes": "https://sec.cloudapps.cisco.com/security/center/content/CiscoSecurityAdvisory/cisco-sa-iosxe-webui-privesc-j22SaA4z;  https://nvd.nist.gov/vuln/detail/CVE-2023-20273", "product": "Cisco IOS XE Web UI", "requiredAction": "Verify that instances of Cisco IOS XE Web UI are in compliance with BOD 23-02 and apply mitigations per vendor instructions. For affected products (Cisco IOS XE Web UI exposed to the internet or to untrusted networks), follow vendor instructions to determine if a system may have been compromised and immediately report positive findings to CISA.", "shortDescription": "Cisco IOS XE contains a command injection vulnerability in the web user interface. When chained with CVE-2023-20198, the attacker can leverage the new local user to elevate privilege to root and write the implant to the file system. Cisco identified CVE-2023-20273 as the vulnerability exploited to deploy the implant. CVE-2021-1435, previously associated with the exploitation events, is no longer believed to be related to this activity.", "vendorProject": "Cisco", "vulnerabilityName": "Cisco IOS XE Web UI Command Injection Vulnerability"}',NULL,0,154,'{"source_id": "cisa-kev", "content_hash": "AA3225536AA7E1DFF8C9E7C33A7493BB167211269087DB9BD348547897884C93"}','2026-08-28T13:24:57Z','cisa-kev','Current feed at retrieval',NULL,'CVE-2023-20273','AA3225536AA7E1DFF8C9E7C33A7493BB167211269087DB9BD348547897884C93','phase6a-1');
