PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE posts(
 id TEXT PRIMARY KEY,
 title TEXT NOT NULL,
 summary TEXT NOT NULL,
 category TEXT NOT NULL CHECK(category IN ('malware','threat-actor','analysis')),
 source TEXT NOT NULL,
 published_at TEXT NOT NULL
);
CREATE TABLE threat_iocs(
 id TEXT PRIMARY KEY, indicator TEXT NOT NULL, kind TEXT NOT NULL,
 source TEXT NOT NULL, confidence INTEGER NOT NULL DEFAULT 0,
 severity TEXT, context TEXT, observed_at TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE malware_reports(
 id TEXT PRIMARY KEY, title TEXT NOT NULL, sha256 TEXT, family TEXT,
 summary TEXT NOT NULL, source TEXT NOT NULL, severity TEXT,
 report_json TEXT NOT NULL, published_at TEXT NOT NULL,
 created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE IF NOT EXISTS "d1_migrations"(
		id         INTEGER PRIMARY KEY AUTOINCREMENT,
		name       TEXT UNIQUE,
		applied_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL
);
CREATE TABLE `actors` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`aliases` text,
	`country` text,
	`motivation` text,
	`description` text,
	`first_seen` text,
	`last_active` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `ai_runs` (
	`id` text PRIMARY KEY NOT NULL,
	`workflow` text NOT NULL,
	`model_id` text NOT NULL,
	`prompt_tokens` integer,
	`completion_tokens` integer,
	`cost_estimated_usd` real,
	`duration_ms` integer,
	`status` text NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
, prompt_version text, input_hash text, output_hash text, retrieved_document_ids text, retrieved_chunk_ids text, retrieved_event_ids text, retrieved_evidence_ids text, confidence real, error_code text);
CREATE TABLE `alerts` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`watchlist_id` text,
	`event_id` text,
	`title` text NOT NULL,
	`message` text NOT NULL,
	`severity` text NOT NULL,
	`is_read` integer DEFAULT false NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`watchlist_id`) REFERENCES `watchlists`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`event_id`) REFERENCES `intelligence_events`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `articles` (
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`slug` text NOT NULL,
	`dek` text,
	`content` text NOT NULL,
	`excerpt` text,
	`author` text DEFAULT 'ZAYRON-X Intelligence Crew' NOT NULL,
	`category` text NOT NULL,
	`tags` text,
	`severity` text,
	`confidence` real,
	`hero_media_url` text,
	`ai_summary` text,
	`fbr_score` real,
	`read_time` integer,
	`views` integer DEFAULT 0 NOT NULL,
	`is_published` integer DEFAULT false NOT NULL,
	`is_featured` integer DEFAULT false NOT NULL,
	`is_breaking` integer DEFAULT false NOT NULL,
	`canonical_intel_event_id` text,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`canonical_intel_event_id`) REFERENCES `intelligence_events`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `audit_events` (
	`id` text PRIMARY KEY NOT NULL,
	`actor_id` text,
	`action` text NOT NULL,
	`target_type` text NOT NULL,
	`target_id` text NOT NULL,
	`correlation_id` text,
	`details` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `campaigns` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`actor_id` text,
	`target_sectors` text,
	`target_regions` text,
	`description` text,
	`start_date` text,
	`end_date` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`actor_id`) REFERENCES `actors`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `evidence` (
	`id` text PRIMARY KEY NOT NULL,
	`event_id` text NOT NULL,
	`source_id` text,
	`source_message_id` text,
	`type` text NOT NULL,
	`url` text,
	`weight` real DEFAULT 1 NOT NULL,
	`snippet` text,
	`reviewer_state` text DEFAULT 'UNREVIEWED',
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`event_id`) REFERENCES `intelligence_events`(`id`) ON UPDATE no action ON DELETE cascade,
	FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`source_message_id`) REFERENCES `source_messages`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `feature_usage` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`feature` text NOT NULL,
	`usage_count` integer DEFAULT 1 NOT NULL,
	`period` text NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `intelligence_events` (
	`id` text PRIMARY KEY NOT NULL,
	`type` text NOT NULL,
	`title` text NOT NULL,
	`summary` text,
	`severity` text NOT NULL,
	`confidence` real DEFAULT 0.5 NOT NULL,
	`status` text DEFAULT 'UNASSESSED' NOT NULL,
	`content_hash` text NOT NULL,
	`first_seen_at` text NOT NULL,
	`last_updated_at` text NOT NULL,
	`entities_json` text,
	`mitre_matrix` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `iocs` (
	`id` text PRIMARY KEY NOT NULL,
	`type` text NOT NULL,
	`normalized_value` text NOT NULL,
	`event_id` text,
	`malware_id` text,
	`threat_actor_id` text,
	`confidence` real DEFAULT 0.8 NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`event_id`) REFERENCES `intelligence_events`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`malware_id`) REFERENCES `malware`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`threat_actor_id`) REFERENCES `actors`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `jobs` (
	`id` text PRIMARY KEY NOT NULL,
	`organization_id` text,
	`title` text NOT NULL,
	`slug` text NOT NULL,
	`company_name` text NOT NULL,
	`company_logo_url` text,
	`employment_type` text NOT NULL,
	`location_type` text NOT NULL,
	`location_city` text,
	`location_country` text,
	`min_salary` integer,
	`max_salary` integer,
	`currency` text DEFAULT 'USD' NOT NULL,
	`description` text NOT NULL,
	`apply_url` text NOT NULL,
	`is_featured` integer DEFAULT false NOT NULL,
	`is_verified` integer DEFAULT false NOT NULL,
	`status` text DEFAULT 'PENDING_REVIEW' NOT NULL,
	`expires_at` text NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `malware` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`type` text,
	`family` text,
	`description` text,
	`yara_rule` text,
	`sigma_rule` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `organizations` (
	`id` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`slug` text NOT NULL,
	`domain` text,
	`verified` integer DEFAULT false NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `payment_sessions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text,
	`idempotency_key` text NOT NULL,
	`provider` text NOT NULL,
	`provider_session_id` text,
	`amount` integer NOT NULL,
	`currency` text DEFAULT 'USD' NOT NULL,
	`status` text DEFAULT 'NEW' NOT NULL,
	`metadata` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `relations` (
	`id` text PRIMARY KEY NOT NULL,
	`source_entity_type` text NOT NULL,
	`source_entity_id` text NOT NULL,
	`target_entity_type` text NOT NULL,
	`target_entity_id` text NOT NULL,
	`relation_type` text NOT NULL,
	`confidence` real DEFAULT 1 NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `reports` (
	`id` text PRIMARY KEY NOT NULL,
	`title` text NOT NULL,
	`slug` text NOT NULL,
	`abstract` text NOT NULL,
	`pdf_r2_key` text,
	`tier_required` text DEFAULT 'pro' NOT NULL,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `social_assets` (
	`id` text PRIMARY KEY NOT NULL,
	`event_id` text,
	`article_id` text,
	`platform` text NOT NULL,
	`format` text NOT NULL,
	`status` text DEFAULT 'DRAFT' NOT NULL,
	`body` text NOT NULL,
	`media_urls` text,
	`scheduled_at` text,
	`idempotency_key` text NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`event_id`) REFERENCES `intelligence_events`(`id`) ON UPDATE no action ON DELETE no action,
	FOREIGN KEY (`article_id`) REFERENCES `articles`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `social_publications` (
	`id` text PRIMARY KEY NOT NULL,
	`asset_id` text NOT NULL,
	`platform` text NOT NULL,
	`external_post_id` text,
	`status` text NOT NULL,
	`attempts` integer DEFAULT 0 NOT NULL,
	`next_attempt_at` text,
	`error_message` text,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`asset_id`) REFERENCES `social_assets`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `source_messages` (
	`id` text PRIMARY KEY NOT NULL,
	`source_id` text NOT NULL,
	`external_message_id` text NOT NULL,
	`content_hash` text NOT NULL,
	`raw_content` text NOT NULL,
	`normalized_content` text,
	`original_language` text,
	`parsed_entities` text,
	`status` text DEFAULT 'PENDING' NOT NULL,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`source_id`) REFERENCES `sources`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `sources` (
	`id` text PRIMARY KEY NOT NULL,
	`display_name` text NOT NULL,
	`url` text,
	`source_type` text NOT NULL,
	`language` text DEFAULT 'en' NOT NULL,
	`region` text,
	`trust_score` real DEFAULT 0.5 NOT NULL,
	`priority` text DEFAULT 'B' NOT NULL,
	`status` text DEFAULT 'ENABLED' NOT NULL,
	`enabled` integer DEFAULT true NOT NULL,
	`last_seen_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `subscriptions` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`plan` text NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`current_period_start` text NOT NULL,
	`current_period_end` text NOT NULL,
	`cancel_at_period_end` integer DEFAULT false NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `ttp_mappings` (
	`id` text PRIMARY KEY NOT NULL,
	`mitre_ttp_id` text NOT NULL,
	`technique_name` text NOT NULL,
	`tactic` text NOT NULL,
	`event_id` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`event_id`) REFERENCES `intelligence_events`(`id`) ON UPDATE no action ON DELETE no action
);
CREATE TABLE `users` (
	`id` text PRIMARY KEY NOT NULL,
	`email` text NOT NULL,
	`name` text,
	`role` text DEFAULT 'free_user' NOT NULL,
	`avatar_url` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `vulnerabilities` (
	`id` text PRIMARY KEY NOT NULL,
	`cve_id` text NOT NULL,
	`title` text NOT NULL,
	`description` text,
	`severity` text NOT NULL,
	`cvss_score` real,
	`cvss_vector` text,
	`epss_score` real,
	`is_exploited_in_wild` integer DEFAULT false NOT NULL,
	`affected_vendor` text,
	`affected_product` text,
	`patch_url` text,
	`published_at` text,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `watchlists` (
	`id` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`name` text NOT NULL,
	`rules_json` text NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `knowledge_documents` (
  `id` text PRIMARY KEY NOT NULL,
  `title` text NOT NULL,
  `author` text,
  `publisher` text,
  `publication_date` text,
  `version` text,
  `license` text,
  `source_url` text,
  `document_type` text NOT NULL,
  `topic` text,
  `authority_tier` integer NOT NULL,
  `content_hash` text NOT NULL,
  `metadata` text,
  `created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL,
  `updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
);
CREATE TABLE `knowledge_chunks` (
  `id` text PRIMARY KEY NOT NULL,
  `document_id` text NOT NULL REFERENCES `knowledge_documents`(`id`) ON DELETE CASCADE,
  `section` text,
  `page` integer,
  `text` text NOT NULL,
  `embedding_id` text,
  `authority_tier` integer NOT NULL,
  `token_count` integer,
  `metadata` text,
  `created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')) NOT NULL
, source_id TEXT, version TEXT, chapter TEXT, subsection TEXT, content_hash TEXT, processing_version TEXT);
CREATE TABLE evidence_ledger (
  claim_id TEXT PRIMARY KEY NOT NULL,
  event_id TEXT NOT NULL,
  claim TEXT NOT NULL,
  classification TEXT NOT NULL CHECK (classification IN ('OBSERVED_FACT', 'REPORTED_CLAIM', 'INFERENCE', 'ANALYST_ASSESSMENT', 'UNKNOWN')),
  source_id TEXT,
  source_tier INTEGER,
  source_url TEXT,
  published_at TEXT,
  retrieved_at TEXT NOT NULL,
  evidence_type TEXT NOT NULL,
  supports_or_contradicts TEXT NOT NULL CHECK (supports_or_contradicts IN ('SUPPORTS', 'CONTRADICTS', 'NEUTRAL')),
  citation TEXT,
  content_hash TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  FOREIGN KEY (event_id) REFERENCES intelligence_events(id) ON DELETE CASCADE,
  FOREIGN KEY (source_id) REFERENCES sources(id) ON DELETE SET NULL
);
CREATE TABLE knowledge_artifacts (
  id TEXT PRIMARY KEY,
  document_id TEXT REFERENCES knowledge_documents(id) ON DELETE CASCADE,
  source_id TEXT NOT NULL,
  title TEXT NOT NULL,
  author TEXT,
  organization TEXT,
  publisher TEXT,
  publication_date TEXT,
  edition TEXT,
  version TEXT NOT NULL,
  license TEXT NOT NULL,
  legal_download_status TEXT NOT NULL,
  official_url TEXT NOT NULL,
  authority_tier INTEGER NOT NULL,
  r2_object_key TEXT NOT NULL UNIQUE,
  mime_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,
  sha256 TEXT NOT NULL UNIQUE,
  page_count INTEGER,
  processing_status TEXT NOT NULL,
  chunk_count INTEGER NOT NULL DEFAULT 0,
  embedding_status TEXT NOT NULL DEFAULT 'UNVERIFIED',
  retrieval_status TEXT NOT NULL DEFAULT 'UNVERIFIED',
  retrieved_at TEXT NOT NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%SZ', 'now'))
);
DELETE FROM sqlite_sequence;
