CREATE INDEX idx_posts_category_published ON posts(category,published_at DESC);
CREATE INDEX idx_ioc_observed ON threat_iocs(observed_at DESC);
CREATE INDEX idx_ioc_kind_indicator ON threat_iocs(kind,indicator);
CREATE INDEX idx_malware_published ON malware_reports(published_at DESC);
CREATE INDEX idx_malware_sha256 ON malware_reports(sha256);
