CREATE UNIQUE INDEX `idx_actors_slug` ON `actors` (`slug`);
CREATE INDEX `idx_ai_runs_workflow_status` ON `ai_runs` (`workflow`,`status`);
CREATE INDEX `idx_alerts_user_read` ON `alerts` (`user_id`,`is_read`);
CREATE UNIQUE INDEX `articles_slug_unique` ON `articles` (`slug`);
CREATE UNIQUE INDEX `idx_articles_slug` ON `articles` (`slug`);
CREATE INDEX `idx_articles_category_published` ON `articles` (`category`,`is_published`);
CREATE INDEX `idx_articles_published_at` ON `articles` (`published_at`);
CREATE INDEX `idx_audit_events_created_at` ON `audit_events` (`created_at`);
CREATE INDEX `idx_audit_events_actor` ON `audit_events` (`actor_id`);
CREATE UNIQUE INDEX `campaigns_slug_unique` ON `campaigns` (`slug`);
CREATE UNIQUE INDEX `idx_campaigns_slug` ON `campaigns` (`slug`);
CREATE INDEX `idx_evidence_event_id` ON `evidence` (`event_id`);
CREATE INDEX `idx_evidence_source_id` ON `evidence` (`source_id`);
CREATE UNIQUE INDEX `idx_feature_usage_user_feat_period` ON `feature_usage` (`user_id`,`feature`,`period`);
CREATE INDEX `idx_intel_events_content_hash` ON `intelligence_events` (`content_hash`);
CREATE INDEX `idx_intel_events_timeline` ON `intelligence_events` (`first_seen_at`,`last_updated_at`);
CREATE INDEX `idx_intel_events_severity` ON `intelligence_events` (`severity`);
CREATE INDEX `idx_intel_events_status` ON `intelligence_events` (`status`);
CREATE INDEX `idx_iocs_type_val` ON `iocs` (`type`,`normalized_value`);
CREATE UNIQUE INDEX `jobs_slug_unique` ON `jobs` (`slug`);
CREATE UNIQUE INDEX `idx_jobs_slug` ON `jobs` (`slug`);
CREATE INDEX `idx_jobs_status_expires` ON `jobs` (`status`,`expires_at`);
CREATE INDEX `idx_jobs_location` ON `jobs` (`location_type`,`location_country`);
CREATE UNIQUE INDEX `malware_slug_unique` ON `malware` (`slug`);
CREATE UNIQUE INDEX `idx_malware_slug` ON `malware` (`slug`);
CREATE UNIQUE INDEX `organizations_slug_unique` ON `organizations` (`slug`);
CREATE UNIQUE INDEX `idx_organizations_slug` ON `organizations` (`slug`);
CREATE UNIQUE INDEX `payment_sessions_idempotency_key_unique` ON `payment_sessions` (`idempotency_key`);
CREATE UNIQUE INDEX `idx_payment_sessions_idempotency` ON `payment_sessions` (`idempotency_key`);
CREATE INDEX `idx_payment_sessions_status` ON `payment_sessions` (`status`);
CREATE INDEX `idx_relations_source` ON `relations` (`source_entity_type`,`source_entity_id`);
CREATE INDEX `idx_relations_target` ON `relations` (`target_entity_type`,`target_entity_id`);
CREATE UNIQUE INDEX `reports_slug_unique` ON `reports` (`slug`);
CREATE UNIQUE INDEX `idx_reports_slug` ON `reports` (`slug`);
CREATE UNIQUE INDEX `social_assets_idempotency_key_unique` ON `social_assets` (`idempotency_key`);
CREATE UNIQUE INDEX `idx_social_assets_idempotency` ON `social_assets` (`idempotency_key`);
CREATE INDEX `idx_social_assets_platform_status` ON `social_assets` (`platform`,`status`);
CREATE INDEX `idx_social_pub_status_next` ON `social_publications` (`status`,`next_attempt_at`);
CREATE UNIQUE INDEX `idx_source_messages_source_external` ON `source_messages` (`source_id`,`external_message_id`);
CREATE INDEX `idx_source_messages_content_hash` ON `source_messages` (`content_hash`);
CREATE INDEX `idx_source_messages_status` ON `source_messages` (`status`);
CREATE INDEX `idx_sources_status` ON `sources` (`status`);
CREATE INDEX `idx_sources_type` ON `sources` (`source_type`);
CREATE INDEX `idx_subscriptions_user_status` ON `subscriptions` (`user_id`,`status`);
CREATE INDEX `idx_ttp_mappings_ttp` ON `ttp_mappings` (`mitre_ttp_id`);
CREATE UNIQUE INDEX `users_email_unique` ON `users` (`email`);
CREATE UNIQUE INDEX `idx_users_email` ON `users` (`email`);
CREATE UNIQUE INDEX `vulnerabilities_cve_id_unique` ON `vulnerabilities` (`cve_id`);
